export interface Verse {
  id: number;
  arabic: string;
  explication: string;
}

export const AL_BAQARA: Verse[] = [
  { id: 1,   arabic: "الم", explication: "Lettres initiales mystérieuses (Hurûf Muqatta'ât). Seul Allah en connaît le sens précis." },
  { id: 2,   arabic: "ذَٰلِكَ الْكِتَابُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ", explication: "Ce Livre — en lui nul doute — est un guide pour les pieux." },
  { id: 3,   arabic: "الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَاةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ", explication: "Ceux qui croient à l'invisible, accomplissent la prière et font des dons de ce que Nous leur avons accordé." },
  { id: 4,   arabic: "وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ", explication: "Et ceux qui croient à ce qui t'a été révélé et à ce qui a été révélé avant toi, et qui ont la certitude de l'au-delà." },
  { id: 5,   arabic: "أُولَٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُولَٰئِكَ هُمُ الْمُفْلِحُونَ", explication: "Ceux-là sont guidés par leur Seigneur et ce sont eux qui réussiront." },
  { id: 6,   arabic: "إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ", explication: "Certes ceux qui ont mécru — c'est égal pour eux que tu les aies avertis ou non — ils ne croiront pas." },
  { id: 7,   arabic: "خَتَمَ اللَّهُ عَلَىٰ قُلُوبِهِمْ وَعَلَىٰ سَمْعِهِمْ ۖ وَعَلَىٰ أَبْصَارِهِمْ غِشَاوَةٌ ۖ وَلَهُمْ عَذَابٌ عَظِيمٌ", explication: "Allah a scellé leurs cœurs et leurs oreilles ; sur leurs yeux il y a un voile, et pour eux un grand châtiment." },
  { id: 8,   arabic: "وَمِنَ النَّاسِ مَن يَقُولُ آمَنَّا بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ وَمَا هُم بِمُؤْمِنِينَ", explication: "Il y a des gens qui disent : nous croyons en Allah et au Jour dernier. Mais ils ne sont pas croyants." },
  { id: 9,   arabic: "يُخَادِعُونَ اللَّهَ وَالَّذِينَ آمَنُوا وَمَا يَخْدَعُونَ إِلَّا أَنفُسَهُمْ وَمَا يَشْعُرُونَ", explication: "Ils cherchent à tromper Allah et les croyants, mais ils ne trompent qu'eux-mêmes sans s'en rendre compte." },
  { id: 10,  arabic: "فِي قُلُوبِهِم مَّرَضٌ فَزَادَهُمُ اللَّهُ مَرَضًا ۖ وَلَهُمْ عَذَابٌ أَلِيمٌ بِمَا كَانُوا يَكْذِبُونَ", explication: "Dans leurs cœurs il y a une maladie — qu'Allah a aggravée. Un douloureux châtiment les attend pour leur mensonge." },
  { id: 11,  arabic: "وَإِذَا قِيلَ لَهُمْ لَا تُفْسِدُوا فِي الْأَرْضِ قَالُوا إِنَّمَا نَحْنُ مُصْلِحُونَ", explication: "Quand on leur dit : ne semez pas la corruption sur la terre, ils disent : nous ne faisons que réformer !" },
  { id: 12,  arabic: "أَلَا إِنَّهُمْ هُمُ الْمُفْسِدُونَ وَلَٰكِن لَّا يَشْعُرُونَ", explication: "Certes ce sont eux les corrupteurs, mais ils ne s'en rendent pas compte." },
  { id: 13,  arabic: "وَإِذَا قِيلَ لَهُمْ آمِنُوا كَمَا آمَنَ النَّاسُ قَالُوا أَنُؤْمِنُ كَمَا آمَنَ السُّفَهَاءُ ۗ أَلَا إِنَّهُمْ هُمُ السُّفَهَاءُ وَلَٰكِن لَّا يَعْلَمُونَ", explication: "Quand on leur dit de croire comme les autres, ils demandent si on doit croire comme des idiots. Ce sont eux les idiots, mais ils ne le savent pas." },
  { id: 14,  arabic: "وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا إِلَىٰ شَيَاطِينِهِمْ قَالُوا إِنَّا مَعَكُمْ إِنَّمَا نَحْنُ مُسْتَهْزِئُونَ", explication: "Face aux croyants ils disent qu'ils croient ; seuls avec leurs démons ils affirment être avec eux et se moquent des croyants." },
  { id: 15,  arabic: "اللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِي طُغْيَانِهِمْ يَعْمَهُونَ", explication: "Allah Se moque d'eux et les laisse errer dans leur rébellion." },
  { id: 16,  arabic: "أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَالَةَ بِالْهُدَىٰ فَمَا رَبِحَت تِّجَارَتُهُمْ وَمَا كَانُوا مُهْتَدِينَ", explication: "Ceux-là ont échangé la guidance contre l'égarement : leur commerce n'a pas été profitable et ils ne sont pas guidés." },
  { id: 17,  arabic: "مَثَلُهُمْ كَمَثَلِ الَّذِي اسْتَوْقَدَ نَارًا فَلَمَّا أَضَاءَتْ مَا حَوْلَهُ ذَهَبَ اللَّهُ بِنُورِهِمْ وَتَرَكَهُمْ فِي ظُلُمَاتٍ لَّا يُبْصِرُونَ", explication: "Leur exemple est celui de quelqu'un qui allume un feu — quand la lumière l'entoure, Allah emporte leur lumière et les laisse dans des ténèbres." },
  { id: 18,  arabic: "صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَرْجِعُونَ", explication: "Sourds, muets, aveugles — ils ne reviendront pas (à la vérité)." },
  { id: 19,  arabic: "أَوْ كَصَيِّبٍ مِّنَ السَّمَاءِ فِيهِ ظُلُمَاتٌ وَرَعْدٌ وَبَرْقٌ يَجْعَلُونَ أَصَابِعَهُمْ فِي آذَانِهِم مِّنَ الصَّوَاعِقِ حَذَرَ الْمَوْتِ ۚ وَاللَّهُ مُحِيطٌ بِالْكَافِرِينَ", explication: "Ou tel un orage du ciel avec ténèbres, tonnerre et éclair — ils mettent leurs doigts dans leurs oreilles par crainte de la foudre mortelle. Allah encercle les mécréants." },
  { id: 20,  arabic: "يَكَادُ الْبَرْقُ يَخْطَفُ أَبْصَارَهُمْ ۖ كُلَّمَا أَضَاءَ لَهُم مَّشَوْا فِيهِ وَإِذَا أَظْلَمَ عَلَيْهِمْ قَامُوا ۚ وَلَوْ شَاءَ اللَّهُ لَذَهَبَ بِسَمْعِهِمْ وَأَبْصَارِهِمْ ۚ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", explication: "L'éclair faillit leur ravir la vue. Quand il brille ils avancent, quand il s'obscurcit ils s'arrêtent. Si Allah voulait, Il leur prendrait l'ouïe et la vue. Il est Puissant sur toute chose." },
  { id: 21,  arabic: "يَا أَيُّهَا النَّاسُ اعْبُدُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ وَالَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", explication: "Ô humanité ! Adorez votre Seigneur qui vous a créés, vous et ceux d'avant vous — afin que vous soyez pieux." },
  { id: 22,  arabic: "الَّذِي جَعَلَ لَكُمُ الْأَرْضَ فِرَاشًا وَالسَّمَاءَ بِنَاءً وَأَنزَلَ مِنَ السَّمَاءِ مَاءً فَأَخْرَجَ بِهِ مِنَ الثَّمَرَاتِ رِزْقًا لَّكُمْ ۖ فَلَا تَجْعَلُوا لِلَّهِ أَندَادًا وَأَنتُمْ تَعْلَمُونَ", explication: "Celui qui a fait de la terre un tapis pour vous, du ciel un édifice, et a fait descendre de l'eau du ciel pour vous nourrir. N'associez donc rien à Allah en sachant." },
  { id: 23,  arabic: "وَإِن كُنتُمْ فِي رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا بِسُورَةٍ مِّن مِّثْلِهِ وَادْعُوا شُهَدَاءَكُم مِّن دُونِ اللَّهِ إِنْ كُنتُمْ صَادِقِينَ", explication: "Si vous avez un doute sur ce que Nous avons révélé à Notre Serviteur, apportez une seule sourate comparable et appelez vos témoins hors d'Allah, si vous êtes véridiques." },
  { id: 24,  arabic: "فَإِن لَّمْ تَفْعَلُوا وَلَن تَفْعَلُوا فَاتَّقُوا النَّارَ الَّتِي وَقُودُهَا النَّاسُ وَالْحِجَارَةُ ۖ أُعِدَّتْ لِلْكَافِرِينَ", explication: "Si vous ne le faites pas — et jamais vous ne le ferez — craignez le Feu dont le combustible est les hommes et les pierres, préparé pour les mécréants." },
  { id: 25,  arabic: "وَبَشِّرِ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أَنَّ لَهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ۖ كُلَّمَا رُزِقُوا مِنْهَا مِن ثَمَرَةٍ رِّزْقًا قَالُوا هَٰذَا الَّذِي رُزِقْنَا مِن قَبْلُ ۖ وَأُتُوا بِهِ مُتَشَابِهًا ۖ وَلَهُمْ فِيهَا أَزْوَاجٌ مُّطَهَّرَةٌ ۖ وَهُمْ فِيهَا خَالِدُونَ", explication: "Annonce la bonne nouvelle aux croyants vertueux : des jardins sous lesquels coulent des rivières, éternité avec des épouses purifiées." },
  { id: 26,  arabic: "إِنَّ اللَّهَ لَا يَسْتَحْيِي أَن يَضْرِبَ مَثَلًا مَّا بَعُوضَةً فَمَا فَوْقَهَا ۚ فَأَمَّا الَّذِينَ آمَنُوا فَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ ۖ وَأَمَّا الَّذِينَ كَفَرُوا فَيَقُولُونَ مَاذَا أَرَادَ اللَّهُ بِهَٰذَا مَثَلًا ۘ يُضِلُّ بِهِ كَثِيرًا وَيَهْدِي بِهِ كَثِيرًا ۚ وَمَا يُضِلُّ بِهِ إِلَّا الْفَاسِقِينَ", explication: "Allah n'a pas honte de donner en exemple un moustique ou plus petit encore. Les croyants savent que c'est la vérité de leur Seigneur ; les mécréants demandent ce qu'Allah veut dire." },
  { id: 27,  arabic: "الَّذِينَ يَنقُضُونَ عَهْدَ اللَّهِ مِن بَعْدِ مِيثَاقِهِ وَيَقْطَعُونَ مَا أَمَرَ اللَّهُ بِهِ أَن يُوصَلَ وَيُفْسِدُونَ فِي الْأَرْضِ ۚ أُولَٰئِكَ هُمُ الْخَاسِرُونَ", explication: "Ceux qui violent le pacte d'Allah, rompent ce qu'Il a ordonné de maintenir et sèment la corruption — ceux-là sont les perdants." },
  { id: 28,  arabic: "كَيْفَ تَكْفُرُونَ بِاللَّهِ وَكُنتُمْ أَمْوَاتًا فَأَحْيَاكُمْ ۖ ثُمَّ يُمِيتُكُمْ ثُمَّ يُحْيِيكُمْ ثُمَّ إِلَيْهِ تُرْجَعُونَ", explication: "Comment pouvez-vous nier Allah, alors que vous étiez morts et Il vous a vivifiés, puis Il vous fera mourir, puis Il vous vivifiera à nouveau, et vers Lui vous retournerez ?" },
  { id: 29,  arabic: "هُوَ الَّذِي خَلَقَ لَكُم مَّا فِي الْأَرْضِ جَمِيعًا ثُمَّ اسْتَوَىٰ إِلَى السَّمَاءِ فَسَوَّاهُنَّ سَبْعَ سَمَاوَاتٍ ۚ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ", explication: "C'est Lui qui a créé pour vous tout ce qui est sur terre, puis S'est tourné vers le ciel pour en faire sept cieux. Il est Omniscient." },
  { id: 30,  arabic: "وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً ۖ قَالُوا أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ الدِّمَاءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّي أَعْلَمُ مَا لَا تَعْلَمُونَ", explication: "Quand ton Seigneur dit aux anges : Je vais établir un vicaire sur terre. Ils demandèrent s'Il allait y mettre qui corrompt et répand le sang. Allah dit : Je sais ce que vous ne savez pas." },
  { id: 31,  arabic: "وَعَلَّمَ آدَمَ الْأَسْمَاءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى الْمَلَائِكَةِ فَقَالَ أَنبِئُونِي بِأَسْمَاءِ هَٰؤُلَاءِ إِنْ كُنتُمْ صَادِقِينَ", explication: "Allah enseigna à Adam les noms de toutes choses, puis les présenta aux anges et dit : Informez-Moi des noms de ceux-ci si vous êtes véridiques." },
  { id: 32,  arabic: "قَالُوا سُبْحَانَكَ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا ۖ إِنَّكَ أَنتَ الْعَلِيمُ الْحَكِيمُ", explication: "Ils dirent : Gloire à Toi ! Nous n'avons de science que ce que Tu nous as enseigné. Tu es l'Omniscient, le Sage." },
  { id: 33,  arabic: "قَالَ يَا آدَمُ أَنبِئْهُم بِأَسْمَائِهِمْ ۖ فَلَمَّا أَنبَأَهُم بِأَسْمَائِهِمْ قَالَ أَلَمْ أَقُل لَّكُمْ إِنِّي أَعْلَمُ غَيْبَ السَّمَاوَاتِ وَالْأَرْضِ وَأَعْلَمُ مَا تُبْدُونَ وَمَا كُنتُمْ تَكْتُمُونَ", explication: "Allah dit : Adam, informe-les de leurs noms ! Quand Adam les informa, Allah dit : Ne vous avais-Je pas dit que Je connais le secret des cieux et de la terre ?" },
  { id: 34,  arabic: "وَإِذْ قُلْنَا لِلْمَلَائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِيسَ أَبَىٰ وَاسْتَكْبَرَ وَكَانَ مِنَ الْكَافِرِينَ", explication: "Nous avons dit aux anges : Prosternez-vous devant Adam. Ils se prosternèrent, sauf Iblis qui refusa par orgueil et devint mécréant." },
  { id: 35,  arabic: "وَقُلْنَا يَا آدَمُ اسْكُنْ أَنتَ وَزَوْجُكَ الْجَنَّةَ وَكُلَا مِنْهَا رَغَدًا حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ", explication: "Nous dîmes : Adam, habite avec ton épouse au Paradis, mangez-y abondamment où vous voulez, mais n'approchez pas de cet arbre — vous seriez des injustes." },
  { id: 36,  arabic: "فَأَزَلَّهُمَا الشَّيْطَانُ عَنْهَا فَأَخْرَجَهُمَا مِمَّا كَانَا فِيهِ ۖ وَقُلْنَا اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ۖ وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ وَمَتَاعٌ إِلَىٰ حِينٍ", explication: "Le Diable les fit trébucher et les chassa du Paradis. Nous dîmes : Descendez, vous êtes ennemis les uns des autres ; vous aurez une demeure sur terre pour un temps." },
  { id: 37,  arabic: "فَتَلَقَّىٰ آدَمُ مِن رَّبِّهِ كَلِمَاتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ", explication: "Adam reçut de son Seigneur des paroles et Il lui pardonna. Il est le Clément, le Miséricordieux." },
  { id: 38,  arabic: "قُلْنَا اهْبِطُوا مِنْهَا جَمِيعًا ۖ فَإِمَّا يَأْتِيَنَّكُم مِّنِّي هُدًى فَمَن تَبِعَ هُدَايَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", explication: "Nous dîmes : Descendez tous. Si une guidance vous vient de Moi, ceux qui la suivront n'auront ni crainte ni tristesse." },
  { id: 39,  arabic: "وَالَّذِينَ كَفَرُوا وَكَذَّبُوا بِآيَاتِنَا أُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ", explication: "Ceux qui mécroient et traitent Nos signes de mensonges seront les gens du Feu, y demeurant éternellement." },
  { id: 40,  arabic: "يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَوْفُوا بِعَهْدِي أُوفِ بِعَهْدِكُمْ وَإِيَّايَ فَارْهَبُونِ", explication: "Ô Banû Isrâ'îl ! Rappelez-vous Mon bienfait envers vous, respectez votre pacte envers Moi, Je respecterai le Mien envers vous. Et n'ayez de crainte que pour Moi." },
  { id: 41,  arabic: "وَآمِنُوا بِمَا أَنزَلْتُ مُصَدِّقًا لِّمَا مَعَكُمْ وَلَا تَكُونُوا أَوَّلَ كَافِرٍ بِهِ ۖ وَلَا تَشْتَرُوا بِآيَاتِي ثَمَنًا قَلِيلًا وَإِيَّايَ فَاتَّقُونِ", explication: "Croyez en ce que J'ai révélé, confirmant ce que vous avez. Ne soyez pas les premiers à le nier. Ne vendez pas Mes versets pour un vil prix. N'ayez de piété que pour Moi." },
  { id: 42,  arabic: "وَلَا تَلْبِسُوا الْحَقَّ بِالْبَاطِلِ وَتَكْتُمُوا الْحَقَّ وَأَنتُمْ تَعْلَمُونَ", explication: "Ne confondez pas la vérité avec le mensonge et ne cachez pas la vérité en sachant." },
  { id: 43,  arabic: "وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ وَارْكَعُوا مَعَ الرَّاكِعِينَ", explication: "Accomplissez la prière, acquittez la Zakât et inclinez-vous avec ceux qui s'inclinent." },
  { id: 44,  arabic: "أَتَأْمُرُونَ النَّاسَ بِالْبِرِّ وَتَنسَوْنَ أَنفُسَكُمْ وَأَنتُمْ تَتْلُونَ الْكِتَابَ ۚ أَفَلَا تَعْقِلُونَ", explication: "Ordonnez-vous aux gens la piété tout en vous oubliant, vous qui récitez le Livre ? Ne raisonnez-vous pas ?" },
  { id: 45,  arabic: "وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ ۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى الْخَاشِعِينَ", explication: "Cherchez secours dans la patience et la prière. C'est certes pénible, sauf pour les humbles." },
  { id: 46,  arabic: "الَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَاقُو رَبِّهِمْ وَأَنَّهُمْ إِلَيْهِ رَاجِعُونَ", explication: "Ceux qui ont la certitude de rencontrer leur Seigneur et de retourner vers Lui." },
  { id: 47,  arabic: "يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ", explication: "Ô Banû Isrâ'îl ! Rappelez-vous Mes bienfaits envers vous et que Je vous ai préférés aux mondes (de votre époque)." },
  { id: 48,  arabic: "وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا شَفَاعَةٌ وَلَا يُؤْخَذُ مِنْهَا عَدْلٌ وَلَا هُمْ يُنصَرُونَ", explication: "Craignez le Jour où nul ne pourra rien pour un autre, nulle intercession ne sera acceptée, nulle rançon ne sera prise, nul secours ne viendra." },
  { id: 49,  arabic: "وَإِذْ نَجَّيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ يُذَبِّحُونَ أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ ۚ وَفِي ذَٰلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ", explication: "Rappelez-vous quand Nous vous avons sauvés de Pharaon qui vous infligeait de cruels tourments, égorgeant vos fils et laissant vivre vos femmes. Une grande épreuve de votre Seigneur." },
  { id: 50,  arabic: "وَإِذْ فَرَقْنَا بِكُمُ الْبَحْرَ فَأَنجَيْنَاكُمْ وَأَغْرَقْنَا آلَ فِرْعَوْنَ وَأَنتُمْ تَنظُرُونَ", explication: "Rappelez-vous quand Nous avons fendu pour vous la mer, Nous vous avons sauvés et noyé les gens de Pharaon sous vos yeux." },
  { id: 51,  arabic: "وَإِذْ وَاعَدْنَا مُوسَىٰ أَرْبَعِينَ لَيْلَةً ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِن بَعْدِهِ وَأَنتُمْ ظَالِمُونَ", explication: "Rappelez-vous quand Nous avons fixé à Moïse quarante nuits de rendez-vous, et vous avez adoré le Veau après lui, étant injustes." },
  { id: 52,  arabic: "ثُمَّ عَفَوْنَا عَنكُم مِّن بَعْدِ ذَٰلِكَ لَعَلَّكُمْ تَشْكُرُونَ", explication: "Puis Nous vous avons pardonné après cela afin que vous soyez reconnaissants." },
  { id: 53,  arabic: "وَإِذْ آتَيْنَا مُوسَى الْكِتَابَ وَالْفُرْقَانَ لَعَلَّكُمْ تَهْتَدُونَ", explication: "Rappelez-vous quand Nous avons donné à Moïse le Livre et le Discernement, afin que vous soyez guidés." },
  { id: 54,  arabic: "وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ يَا قَوْمِ إِنَّكُمْ ظَلَمْتُمْ أَنفُسَكُم بِاتِّخَاذِكُمُ الْعِجْلَ فَتُوبُوا إِلَىٰ بَارِئِكُمْ فَاقْتُلُوا أَنفُسَكُمْ ذَٰلِكُمْ خَيْرٌ لَّكُمْ عِندَ بَارِئِكُمْ فَتَابَ عَلَيْكُمْ ۚ إِنَّهُ هُوَ التَّوَّابُ الرَّحِيمُ", explication: "Quand Moïse dit à son peuple : vous vous êtes injustiés en adorant le Veau. Repentez-vous auprès de votre Créateur — Allah leur pardonna. Il est le Clément, le Miséricordieux." },
  { id: 55,  arabic: "وَإِذْ قُلْتُمْ يَا مُوسَىٰ لَن نُّؤْمِنَ لَكَ حَتَّىٰ نَرَى اللَّهَ جَهْرَةً فَأَخَذَتْكُمُ الصَّاعِقَةُ وَأَنتُمْ تَنظُرُونَ", explication: "Quand vous avez dit : Moïse, nous ne te croirons pas tant que nous ne verrons pas Allah ouvertement. La foudre vous a frappés sous vos propres yeux." },
  { id: 56,  arabic: "ثُمَّ بَعَثْنَاكُم مِّن بَعْدِ مَوْتِكُمْ لَعَلَّكُمْ تَشْكُرُونَ", explication: "Puis Nous vous avons ressuscités après votre mort, afin que vous soyez reconnaissants." },
  { id: 57,  arabic: "وَظَلَّلْنَا عَلَيْكُمُ الْغَمَامَ وَأَنزَلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَىٰ ۖ كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ ۖ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ", explication: "Nous avons fait planer le nuage sur vous et fait descendre la manne et les cailles. Mangez des bonnes choses que Nous vous avons accordées. Ce ne sont pas Nous qu'ils ont lésés, mais eux-mêmes." },
  { id: 58,  arabic: "وَإِذْ قُلْنَا ادْخُلُوا هَٰذِهِ الْقَرْيَةَ فَكُلُوا مِنْهَا حَيْثُ شِئْتُمْ رَغَدًا وَادْخُلُوا الْبَابَ سُجَّدًا وَقُولُوا حِطَّةٌ نَّغْفِرْ لَكُمْ خَطَايَاكُمْ ۚ وَسَنَزِيدُ الْمُحْسِنِينَ", explication: "Entrez dans cette ville et mangez-y abondamment où vous voulez. Entrez par la porte en vous prosternant et dites : Remise de nos péchés. Nous pardonnerons et augmenterons les bienfaiteurs." },
  { id: 59,  arabic: "فَبَدَّلَ الَّذِينَ ظَلَمُوا قَوْلًا غَيْرَ الَّذِي قِيلَ لَهُمْ فَأَنزَلْنَا عَلَى الَّذِينَ ظَلَمُوا رِجْزًا مِّنَ السَّمَاءِ بِمَا كَانُوا يَفْسُقُونَ", explication: "Les injustes changèrent les paroles qu'on leur avait dites — Nous avons fait descendre sur eux un châtiment du ciel pour leur perversité." },
  { id: 60,  arabic: "وَإِذِ اسْتَسْقَىٰ مُوسَىٰ لِقَوْمِهِ فَقُلْنَا اضْرِب بِّعَصَاكَ الْحَجَرَ ۖ فَانفَجَرَتْ مِنْهُ اثْنَتَا عَشْرَةَ عَيْنًا ۖ قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ ۖ كُلُوا وَاشْرَبُوا مِن رِّزْقِ اللَّهِ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ", explication: "Quand Moïse implora de l'eau pour son peuple, Nous dîmes : frappe le rocher de ton bâton. Douze sources en jaillirent. Mangez et buvez de ce qu'Allah vous accorde et ne semez pas la corruption." },
  { id: 61,  arabic: "وَإِذْ قُلْتُمْ يَا مُوسَىٰ لَن نَّصْبِرَ عَلَىٰ طَعَامٍ وَاحِدٍ فَادْعُ لَنَا رَبَّكَ يُخْرِجْ لَنَا مِمَّا تُنبِتُ الْأَرْضُ مِن بَقْلِهَا وَقِثَّائِهَا وَفُومِهَا وَعَدَسِهَا وَبَصَلِهَا ۖ قَالَ أَتَسْتَبْدِلُونَ الَّذِي هُوَ أَدْنَىٰ بِالَّذِي هُوَ خَيْرٌ ۚ اهْبِطُوا مِصْرًا فَإِنَّ لَكُم مَّا سَأَلْتُمْ ۗ وَضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ وَبَاءُوا بِغَضَبٍ مِّنَ اللَّهِ ذَٰلِكَ بِأَنَّهُمْ كَانُوا يَكْفُرُونَ بِآيَاتِ اللَّهِ وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ الْحَقِّ ذَٰلِكَ بِمَا عَصَوا وَّكَانُوا يَعْتَدُونَ", explication: "Ils demandèrent légumes, lentilles et oignons à la place de la manne. Moïse dit : échangez-vous ce qui est supérieur pour ce qui est inférieur ? Descendez dans une ville. L'humiliation les frappa car ils niaient les signes d'Allah et tuaient injustement les prophètes." },
  { id: 62,  arabic: "إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَادُوا وَالنَّصَارَىٰ وَالصَّابِئِينَ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَعَمِلَ صَالِحًا فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", explication: "Ceux qui ont cru, les Juifs, les Chrétiens et les Sabéens — quiconque aura cru en Allah et au Jour dernier et aura fait de bonnes œuvres aura sa récompense." },
  { id: 63,  arabic: "وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاذْكُرُوا مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", explication: "Quand Nous avons pris votre pacte et élevé au-dessus de vous le Mont Sinaï : tenez fermement ce que Nous vous avons donné et rappelez-vous ce qu'il contient — peut-être serez-vous pieux." },
  { id: 64,  arabic: "ثُمَّ تَوَلَّيْتُم مِّن بَعْدِ ذَٰلِكَ ۖ فَلَوْلَا فَضْلُ اللَّهِ عَلَيْكُمْ وَرَحْمَتُهُ لَكُنتُم مِّنَ الْخَاسِرِينَ", explication: "Puis vous vous êtes détournés après cela. Sans la grâce et la miséricorde d'Allah, vous auriez été parmi les perdants." },
  { id: 65,  arabic: "وَلَقَدْ عَلِمْتُمُ الَّذِينَ اعْتَدَوْا مِنكُمْ فِي السَّبْتِ فَقُلْنَا لَهُمْ كُونُوا قِرَدَةً خَاسِئِينَ", explication: "Vous avez su ce qui est arrivé à ceux d'entre vous qui ont transgressé le Sabbat. Nous leur avons dit : soyez des singes méprisables !" },
  { id: 66,  arabic: "فَجَعَلْنَاهَا نَكَالًا لِّمَا بَيْنَ يَدَيْهَا وَمَا خَلْفَهَا وَمَوْعِظَةً لِّلْمُتَّقِينَ", explication: "Nous en avons fait un exemple avertisseur pour leur époque et les suivantes, une leçon pour les pieux." },
  { id: 67,  arabic: "وَإِذْ قَالَ مُوسَىٰ لِقَوْمِهِ إِنَّ اللَّهَ يَأْمُرُكُمْ أَن تَذْبَحُوا بَقَرَةً ۖ قَالُوا أَتَتَّخِذُنَا هُزُوًا ۖ قَالَ أَعُوذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ", explication: "Quand Moïse dit à son peuple : Allah vous ordonne d'immoler une vache. Ils demandèrent s'il se moquait d'eux. Il dit : je me réfugie en Allah d'être parmi les ignorants." },
  { id: 68,  arabic: "قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ ۚ قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا فَارِضٌ وَلَا بِكْرٌ عَوَانٌ بَيْنَ ذَٰلِكَ ۖ فَافْعَلُوا مَا تُؤْمَرُونَ", explication: "Ils demandèrent de consulter son Seigneur. Il dit qu'elle n'est ni vieille ni jeunesse, mais entre les deux. Faites ce qu'on vous ordonne." },
  { id: 69,  arabic: "قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا لَوْنُهَا ۚ قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ صَفْرَاءُ فَاقِعٌ لَّوْنُهَا تَسُرُّ النَّاظِرِينَ", explication: "Ils demandèrent sa couleur. Il dit : une vache d'un jaune vif, agréable à voir." },
  { id: 70,  arabic: "قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ إِنَّ الْبَقَرَ تَشَابَهَ عَلَيْنَا وَإِنَّا إِن شَاءَ اللَّهُ لَمُهْتَدُونَ", explication: "Ils dirent que les vaches se ressemblent pour eux et que si Allah le veut, ils seront guidés." },
  { id: 71,  arabic: "قَالَ إِنَّهُ يَقُولُ إِنَّهَا بَقَرَةٌ لَّا ذَلُولٌ تُثِيرُ الْأَرْضَ وَلَا تَسْقِي الْحَرْثَ مُسَلَّمَةٌ لَّا شِيَةَ فِيهَا ۚ قَالُوا الْآنَ جِئْتَ بِالْحَقِّ ۚ فَذَبَحُوهَا وَمَا كَادُوا يَفْعَلُونَ", explication: "Il dit : non domptée, n'ayant ni labouré ni irrigué, saine, sans tache. Ils dirent : maintenant tu dis la vérité ! Ils l'immolèrent à contrecœur." },
  { id: 72,  arabic: "وَإِذْ قَتَلْتُمْ نَفْسًا فَادَّارَأْتُمْ فِيهَا ۖ وَاللَّهُ مُخْرِجٌ مَّا كُنتُمْ تَكْتُمُونَ", explication: "Vous avez tué quelqu'un puis vous vous en êtes rejetés la responsabilité. Allah allait révéler ce que vous dissimuliez." },
  { id: 73,  arabic: "فَقُلْنَا اضْرِبُوهُ بِبَعْضِهَا ۚ كَذَٰلِكَ يُحْيِي اللَّهُ الْمَوْتَىٰ وَيُرِيكُمْ آيَاتِهِ لَعَلَّكُمْ تَعْقِلُونَ", explication: "Nous avons dit : frappez-le d'une partie de la vache. Ainsi Allah vivifie les morts et vous montre Ses signes afin que vous raisonniez." },
  { id: 74,  arabic: "ثُمَّ قَسَتْ قُلُوبُكُم مِّن بَعْدِ ذَٰلِكَ فَهِيَ كَالْحِجَارَةِ أَوْ أَشَدُّ قَسْوَةً ۚ وَإِنَّ مِنَ الْحِجَارَةِ لَمَا يَتَفَجَّرُ مِنْهُ الْأَنْهَارُ ۚ وَإِنَّ مِنْهَا لَمَا يَشَّقَّقُ فَيَخْرُجُ مِنْهُ الْمَاءُ ۚ وَإِنَّ مِنْهَا لَمَا يَهْبِطُ مِنْ خَشْيَةِ اللَّهِ ۗ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ", explication: "Vos cœurs s'endurcièrent après cela, comme des pierres ou plus encore. Pourtant certaines pierres laissent jaillir des rivières, d'autres se fendent et laissent couler l'eau, d'autres s'effondrent par crainte d'Allah." },
  { id: 75,  arabic: "أَفَتَطْمَعُونَ أَن يُؤْمِنُوا لَكُمْ وَقَدْ كَانَ فَرِيقٌ مِّنْهُمْ يَسْمَعُونَ كَلَامَ اللَّهِ ثُمَّ يُحَرِّفُونَهُ مِن بَعْدِ مَا عَقَلُوهُ وَهُمْ يَعْلَمُونَ", explication: "Espérez-vous qu'ils vous croient, alors qu'un groupe d'entre eux entendait la parole d'Allah puis la falsifiait sciemment après l'avoir comprise ?" },
  { id: 76,  arabic: "وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَا بَعْضُهُمْ إِلَىٰ بَعْضٍ قَالُوا أَتُحَدِّثُونَهُم بِمَا فَتَحَ اللَّهُ عَلَيْكُمْ لِيُحَاجُّوكُم بِهِ عِندَ رَبِّكُمْ ۚ أَفَلَا تَعْقِلُونَ", explication: "Face aux croyants ils disent qu'ils croient. Entre eux ils se demandent pourquoi ils leur raconteraient ce qu'Allah leur a révélé pour qu'ils en fassent argument." },
  { id: 77,  arabic: "أَوَلَا يَعْلَمُونَ أَنَّ اللَّهَ يَعْلَمُ مَا يُسِرُّونَ وَمَا يُعْلِنُونَ", explication: "Ne savent-ils pas qu'Allah sait ce qu'ils cachent et ce qu'ils déclarent ?" },
  { id: 78,  arabic: "وَمِنْهُمْ أُمِّيُّونَ لَا يَعْلَمُونَ الْكِتَابَ إِلَّا أَمَانِيَّ وَإِنْ هُمْ إِلَّا يَظُنُّونَ", explication: "Il y a parmi eux des analphabètes qui ne connaissent le Livre que par ouï-dire et ne font que conjecturer." },
  { id: 79,  arabic: "فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ الْكِتَابَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَٰذَا مِنْ عِندِ اللَّهِ لِيَشْتَرُوا بِهِ ثَمَنًا قَلِيلًا ۖ فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ", explication: "Malheur à ceux qui écrivent le Livre de leurs mains puis disent que c'est d'Allah pour en tirer un vil profit. Malheur à eux pour ce que leurs mains ont écrit !" },
  { id: 80,  arabic: "وَقَالُوا لَن تَمَسَّنَا النَّارُ إِلَّا أَيَّامًا مَّعْدُودَةً ۚ قُلْ أَتَّخَذْتُمْ عِندَ اللَّهِ عَهْدًا فَلَن يُخْلِفَ اللَّهُ عَهْدَهُ ۖ أَمْ تَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ", explication: "Ils ont dit que le Feu ne les touchera que quelques jours. Dis : avez-vous fait un pacte avec Allah ? Ou dites-vous sur Allah ce que vous ne savez pas ?" },
  { id: 81,  arabic: "بَلَىٰ مَن كَسَبَ سَيِّئَةً وَأَحَاطَتْ بِهِ خَطِيئَتُهُ فَأُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ", explication: "Certes ceux qui commettent le mal et sont cernés par leurs péchés sont les gens du Feu où ils demeureront." },
  { id: 82,  arabic: "وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ أَصْحَابُ الْجَنَّةِ ۖ هُمْ فِيهَا خَالِدُونَ", explication: "Ceux qui croient et font de bonnes œuvres seront les gens du Paradis, y demeurant éternellement." },
  { id: 83,  arabic: "وَإِذْ أَخَذْنَا مِيثَاقَ بَنِي إِسْرَائِيلَ لَا تَعْبُدُونَ إِلَّا اللَّهَ وَبِالْوَالِدَيْنِ إِحْسَانًا وَذِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَقُولُوا لِلنَّاسِ حُسْنًا وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ", explication: "Nous avons pris le pacte des Banû Isrâ'îl : n'adorer qu'Allah, traiter bien les parents, les proches, les orphelins et les pauvres, parler bien aux gens, accomplir la prière et la Zakât." },
  { id: 84,  arabic: "وَإِذْ أَخَذْنَا مِيثَاقَكُمْ لَا تَسْفِكُونَ دِمَاءَكُمْ وَلَا تُخْرِجُونَ أَنفُسَكُم مِّن دِيَارِكُمْ ثُمَّ أَقْرَرْتُمْ وَأَنتُمْ تَشْهَدُونَ", explication: "Nous avons pris votre pacte : pas d'effusion de sang entre vous, pas d'expulsion de chez vous. Vous avez confirmé et vous en témoignez." },
  { id: 85,  arabic: "ثُمَّ أَنتُمْ هَٰؤُلَاءِ تَقْتُلُونَ أَنفُسَكُمْ وَتُخْرِجُونَ فَرِيقًا مِّنكُم مِّن دِيَارِهِمْ تَظَاهَرُونَ عَلَيْهِم بِالْإِثْمِ وَالْعُدْوَانِ وَإِن يَأْتُوكُمْ أُسَارَىٰ تُفَادُوهُمْ وَهُوَ مُحَرَّمٌ عَلَيْكُمْ إِخْرَاجُهُمْ ۚ أَفَتُؤْمِنُونَ بِبَعْضِ الْكِتَابِ وَتَكْفُرُونَ بِبَعْضٍ ۚ فَمَا جَزَاءُ مَن يَفْعَلُ ذَٰلِكَ مِنكُمْ إِلَّا خِزْيٌ فِي الْحَيَاةِ الدُّنْيَا ۖ وَيَوْمَ الْقِيَامَةِ يُرَدُّونَ إِلَىٰ أَشَدِّ الْعَذَابِ", explication: "Puis vous vous entre-tuez et expulsez un groupe de chez lui. Croyez-vous en une partie du Livre et niez-vous l'autre ? Le châtiment de celui qui fait cela c'est l'humiliation en ce monde et le plus sévère des châtiments." },
  { id: 86,  arabic: "أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الْحَيَاةَ الدُّنْيَا بِالْآخِرَةِ ۖ فَلَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنصَرُونَ", explication: "Ceux-là ont vendu l'au-delà pour ce monde. Le châtiment ne leur sera pas allégé et ils ne seront pas secourus." },
  { id: 87,  arabic: "وَلَقَدْ آتَيْنَا مُوسَى الْكِتَابَ وَقَفَّيْنَا مِن بَعْدِهِ بِالرُّسُلِ ۖ وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ ۗ أَفَكُلَّمَا جَاءَكُمْ رَسُولٌ بِمَا لَا تَهْوَىٰ أَنفُسُكُمُ اسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ", explication: "Nous avons donné le Livre à Moïse et envoyé des messagers après lui. Nous avons donné à Jésus fils de Marie les preuves et l'appuyé par l'Esprit Saint. Mais chaque fois qu'un messager venait avec ce qui déplaisait, vous vous enorgueillissiez." },
  { id: 88,  arabic: "وَقَالُوا قُلُوبُنَا غُلْفٌ ۚ بَل لَّعَنَهُمُ اللَّهُ بِكُفْرِهِمْ فَقَلِيلًا مَّا يُؤْمِنُونَ", explication: "Ils ont dit : nos cœurs sont enveloppés. Non ! Allah les a maudits pour leur mécréance. Ils ne croient que très peu." },
  { id: 89,  arabic: "وَلَمَّا جَاءَهُمْ كِتَابٌ مِّنْ عِندِ اللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا فَلَمَّا جَاءَهُم مَّا عَرَفُوا كَفَرُوا بِهِ ۚ فَلَعْنَةُ اللَّهِ عَلَى الْكَافِرِينَ", explication: "Quand leur est venu le Livre d'Allah confirmant ce qu'ils avaient — alors qu'ils demandaient auparavant la victoire contre les mécréants — et qu'ils ont reconnu ce Livre, ils l'ont nié. La malédiction d'Allah sur les mécréants !" },
  { id: 90,  arabic: "بِئْسَمَا اشْتَرَوْا بِهِ أَنفُسَهُمْ أَن يَكْفُرُوا بِمَا أَنزَلَ اللَّهُ بَغْيًا أَن يُنَزِّلَ اللَّهُ مِن فَضْلِهِ عَلَىٰ مَن يَشَاءُ مِنْ عِبَادِهِ ۖ فَبَاءُوا بِغَضَبٍ عَلَىٰ غَضَبٍ ۚ وَلِلْكَافِرِينَ عَذَابٌ مُّهِينٌ", explication: "Mauvais est le prix pour lequel ils se sont vendus : nier ce qu'Allah a révélé par jalousie qu'Allah accorde Sa grâce à qui Il veut. Ils se sont attirés colère sur colère." },
  { id: 91,  arabic: "وَإِذَا قِيلَ لَهُمْ آمِنُوا بِمَا أَنزَلَ اللَّهُ قَالُوا نُؤْمِنُ بِمَا أُنزِلَ عَلَيْنَا وَيَكْفُرُونَ بِمَا وَرَاءَهُ وَهُوَ الْحَقُّ مُصَدِّقًا لِّمَا مَعَهُمْ ۗ قُلْ فَلِمَ تَقْتُلُونَ أَنبِيَاءَ اللَّهِ مِن قَبْلُ إِن كُنتُم مُّؤْمِنِينَ", explication: "Quand on leur dit de croire en ce qu'Allah a révélé, ils disent qu'ils croient en ce qui leur a été révélé à eux. Dis : pourquoi alors tuiez-vous les prophètes d'Allah avant si vous étiez croyants ?" },
  { id: 92,  arabic: "وَلَقَدْ جَاءَكُم مُّوسَىٰ بِالْبَيِّنَاتِ ثُمَّ اتَّخَذْتُمُ الْعِجْلَ مِن بَعْدِهِ وَأَنتُمْ ظَالِمُونَ", explication: "Moïse vous est venu avec des preuves évidentes, puis vous avez adoré le Veau après lui, étant des injustes." },
  { id: 93,  arabic: "وَإِذْ أَخَذْنَا مِيثَاقَكُمْ وَرَفَعْنَا فَوْقَكُمُ الطُّورَ خُذُوا مَا آتَيْنَاكُم بِقُوَّةٍ وَاسْمَعُوا ۖ قَالُوا سَمِعْنَا وَعَصَيْنَا وَأُشْرِبُوا فِي قُلُوبِهِمُ الْعِجْلَ بِكُفْرِهِمْ ۚ قُلْ بِئْسَمَا يَأْمُرُكُم بِهِ إِيمَانُكُمْ إِن كُنتُمْ مُّؤْمِنِينَ", explication: "Quand Nous avons pris votre pacte sous le Mont, vous avez dit : nous entendons et nous désobéissons — le Veau pénétrait leurs cœurs par leur mécréance." },
  { id: 94,  arabic: "قُلْ إِن كَانَتْ لَكُمُ الدَّارُ الْآخِرَةُ عِندَ اللَّهِ خَالِصَةً مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ", explication: "Dis : si l'au-delà est exclusivement pour vous sans les autres, souhaitez alors la mort si vous êtes véridiques !" },
  { id: 95,  arabic: "وَلَن يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ ۗ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ", explication: "Ils ne le souhaiteront jamais à cause de ce que leurs mains ont commis. Allah connaît les injustes." },
  { id: 96,  arabic: "وَلَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلَىٰ حَيَاةٍ وَمِنَ الَّذِينَ أَشْرَكُوا ۚ يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِ مِنَ الْعَذَابِ أَن يُعَمَّرَ ۗ وَاللَّهُ بَصِيرٌ بِمَا يَعْمَلُونَ", explication: "Tu les trouveras les plus avides de vivre parmi les gens, même plus que les polythéistes. L'un d'eux aimerait vivre mille ans, mais cela ne l'éloignerait pas du châtiment." },
  { id: 97,  arabic: "قُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَىٰ قَلْبِكَ بِإِذْنِ اللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ وَهُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ", explication: "Dis : quiconque est ennemi de Gabriel — c'est lui qui l'a fait descendre dans ton cœur par permission d'Allah, confirmant ce qui le précède, guide et bonne nouvelle pour les croyants." },
  { id: 98,  arabic: "مَن كَانَ عَدُوًّا لِّلَّهِ وَمَلَائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكَالَ فَإِنَّ اللَّهَ عَدُوٌّ لِّلْكَافِرِينَ", explication: "Quiconque est ennemi d'Allah, de Ses anges, de Ses messagers, de Gabriel et de Michaël — Allah est ennemi des mécréants." },
  { id: 99,  arabic: "وَلَقَدْ أَنزَلْنَا إِلَيْكَ آيَاتٍ بَيِّنَاتٍ ۖ وَمَا يَكْفُرُ بِهَا إِلَّا الْفَاسِقُونَ", explication: "Nous t'avons envoyé des signes évidents — seuls les pervers les nient." },
  { id: 100, arabic: "أَوَكُلَّمَا عَاهَدُوا عَهْدًا نَّبَذَهُ فَرِيقٌ مِّنْهُم ۚ بَلْ أَكْثَرُهُمْ لَا يُؤْمِنُونَ", explication: "Chaque fois qu'ils ont fait un pacte, un groupe d'entre eux le trahissait. La plupart d'entre eux ne croient pas." },
  { id: 101, arabic: "وَلَمَّا جَاءَهُمْ رَسُولٌ مِّنْ عِندِ اللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ نَبَذَ فَرِيقٌ مِّنَ الَّذِينَ أُوتُوا الْكِتَابَ كِتَابَ اللَّهِ وَرَاءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ", explication: "Quand le Messager d'Allah est venu confirmant ce qu'ils avaient, un groupe de ceux à qui le Livre avait été donné a rejeté le Livre d'Allah derrière leur dos comme s'ils ne savaient pas." },
  { id: 102, arabic: "وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَىٰ مُلْكِ سُلَيْمَانَ ۖ وَمَا كَفَرَ سُلَيْمَانُ وَلَٰكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ ۚ وَمَا هُم بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ ۚ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ ۚ لَوْ كَانُوا يَعْلَمُونَ", explication: "Ils ont suivi la magie. Salomon n'a pas mécru, mais les démons ont mécru enseignant la magie et ce qui fut révélé aux deux anges Hârût et Mârût à Babylone. Ceux-ci ne l'enseignaient qu'après avertir que c'est une épreuve." },
  { id: 103, arabic: "وَلَوْ أَنَّهُمْ آمَنُوا وَاتَّقَوْا لَمَثُوبَةٌ مِّنْ عِندِ اللَّهِ خَيْرٌ ۖ لَّوْ كَانُوا يَعْلَمُونَ", explication: "S'ils avaient cru et été pieux, la récompense d'Allah aurait été meilleure — si seulement ils savaient !" },
  { id: 104, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَقُولُوا رَاعِنَا وَقُولُوا انظُرْنَا وَاسْمَعُوا ۗ وَلِلْكَافِرِينَ عَذَابٌ أَلِيمٌ", explication: "Ô croyants ! Ne dites pas Râ'inâ, dites Unzurnâ et écoutez. Les mécréants auront un douloureux châtiment." },
  { id: 105, arabic: "مَّا يَوَدُّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَلَا الْمُشْرِكِينَ أَن يُنَزَّلَ عَلَيْكُم مِّنْ خَيْرٍ مِّن رَّبِّكُمْ ۗ وَاللَّهُ يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ ۚ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ", explication: "Les mécréants parmi les Gens du Livre et les polythéistes ne souhaitent pas qu'un bien vous descende de votre Seigneur. Mais Allah choisit pour Sa miséricorde qui Il veut." },
  { id: 106, arabic: "مَا نَنسَخْ مِنْ آيَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَا أَوْ مِثْلِهَا ۗ أَلَمْ تَعْلَمْ أَنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", explication: "Tout verset que Nous abrogeons ou faisons oublier, Nous apportons un meilleur ou son équivalent. Ne sais-tu pas qu'Allah est Puissant sur toute chose ?" },
  { id: 107, arabic: "أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ ۗ وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ", explication: "Ne sais-tu pas qu'à Allah appartient la royauté des cieux et de la terre, et que vous n'avez hors d'Allah ni protecteur ni secoureur ?" },
  { id: 108, arabic: "أَمْ تُرِيدُونَ أَن تَسْأَلُوا رَسُولَكُمْ كَمَا سُئِلَ مُوسَىٰ مِن قَبْلُ ۗ وَمَن يَتَبَدَّلِ الْكُفْرَ بِالْإِيمَانِ فَقَدْ ضَلَّ سَوَاءَ السَّبِيلِ", explication: "Voulez-vous interroger votre Messager comme Moïse fut interrogé avant ? Quiconque échange la foi contre la mécréance s'est égaré du droit chemin." },
  { id: 109, arabic: "وَدَّ كَثِيرٌ مِّنْ أَهْلِ الْكِتَابِ لَوْ يَرُدُّونَكُم مِّن بَعْدِ إِيمَانِكُمْ كُفَّارًا حَسَدًا مِّنْ عِندِ أَنفُسِهِمْ مِّن بَعْدِ مَا تَبَيَّنَ لَهُمُ الْحَقُّ ۖ فَاعْفُوا وَاصْفَحُوا حَتَّىٰ يَأْتِيَ اللَّهُ بِأَمْرِهِ ۗ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", explication: "Beaucoup des Gens du Livre aimeraient par jalousie vous faire revenir à la mécréance après votre foi, même après que la vérité leur est apparue. Pardonnez et passez outre jusqu'à ce qu'Allah apporte Son ordre." },
  { id: 110, arabic: "وَأَقِيمُوا الصَّلَاةَ وَآتُوا الزَّكَاةَ ۚ وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ ۗ إِنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ", explication: "Accomplissez la prière et acquittez la Zakât. Tout bien que vous avancez pour vous-mêmes, vous le trouverez auprès d'Allah. Allah voit ce que vous faites." },
  { id: 111, arabic: "وَقَالُوا لَن يَدْخُلَ الْجَنَّةَ إِلَّا مَن كَانَ هُودًا أَوْ نَصَارَىٰ ۗ تِلْكَ أَمَانِيُّهُمْ ۗ قُلْ هَاتُوا بُرْهَانَكُمْ إِن كُنتُمْ صَادِقِينَ", explication: "Ils ont dit que nul n'entrera au Paradis sauf les Juifs ou les Chrétiens. Ce sont leurs vœux pieux. Dis : apportez votre preuve si vous êtes véridiques." },
  { id: 112, arabic: "بَلَىٰ مَنْ أَسْلَمَ وَجْهَهُ لِلَّهِ وَهُوَ مُحْسِنٌ فَلَهُ أَجْرُهُ عِندَ رَبِّهِ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", explication: "Certes quiconque soumet son visage à Allah en faisant le bien, il aura sa récompense auprès de son Seigneur. Pas de crainte pour eux ni de tristesse." },
  { id: 113, arabic: "وَقَالَتِ الْيَهُودُ لَيْسَتِ النَّصَارَىٰ عَلَىٰ شَيْءٍ وَقَالَتِ النَّصَارَىٰ لَيْسَتِ الْيَهُودُ عَلَىٰ شَيْءٍ وَهُمْ يَتْلُونَ الْكِتَابَ ۗ كَذَٰلِكَ قَالَ الَّذِينَ لَا يَعْلَمُونَ مِثْلَ قَوْلِهِمْ ۚ فَاللَّهُ يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ", explication: "Les Juifs disent que les Chrétiens ne sont sur rien, et inversement, alors qu'ils récitent le Livre. Allah jugera entre eux le Jour du Jugement." },
  { id: 114, arabic: "وَمَنْ أَظْلَمُ مِمَّن مَّنَعَ مَسَاجِدَ اللَّهِ أَن يُذْكَرَ فِيهَا اسْمُهُ وَسَعَىٰ فِي خَرَابِهَا ۚ أُولَٰئِكَ مَا كَانَ لَهُمْ أَن يَدْخُلُوهَا إِلَّا خَائِفِينَ ۚ لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ", explication: "Qui est plus injuste que celui qui empêche qu'on invoque le nom d'Allah dans Ses mosquées et cherche à les détruire ? Ils ne devraient y entrer qu'avec crainte, humiliation en ce monde et grand châtiment." },
  { id: 115, arabic: "وَلِلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ ۚ فَأَيْنَمَا تُوَلُّوا فَثَمَّ وَجْهُ اللَّهِ ۚ إِنَّ اللَّهَ وَاسِعٌ عَلِيمٌ", explication: "À Allah appartiennent l'Orient et l'Occident. Où que vous vous tourniez, là est la Face d'Allah. Allah est Vaste, Omniscient." },
  { id: 116, arabic: "وَقَالُوا اتَّخَذَ اللَّهُ وَلَدًا ۗ سُبْحَانَهُ ۖ بَل لَّهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۖ كُلٌّ لَّهُ قَانِتُونَ", explication: "Ils ont dit qu'Allah a pris un fils. Gloire à Lui ! Non, à Lui appartient tout ce qui est dans les cieux et la terre, tous Lui sont soumis." },
  { id: 117, arabic: "بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ ۖ وَإِذَا قَضَىٰ أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ", explication: "Il est le Créateur des cieux et de la terre. Quand Il décide une chose, Il dit seulement : Sois ! Et elle est." },
  { id: 118, arabic: "وَقَالَ الَّذِينَ لَا يَعْلَمُونَ لَوْلَا يُكَلِّمُنَا اللَّهُ أَوْ تَأْتِينَا آيَةٌ ۗ كَذَٰلِكَ قَالَ الَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ ۘ تَشَابَهَتْ قُلُوبُهُمْ ۗ قَدْ بَيَّنَّا الْآيَاتِ لِقَوْمٍ يُوقِنُونَ", explication: "Les ignorants ont dit : pourquoi Allah ne nous parle-t-Il pas ou pourquoi ne nous vient-Il pas un signe ? Ceux avant eux ont dit la même chose. Leurs cœurs se ressemblent. Nous avons clarifié les signes pour ceux qui ont la certitude." },
  { id: 119, arabic: "إِنَّا أَرْسَلْنَاكَ بِالْحَقِّ بَشِيرًا وَنَذِيرًا ۖ وَلَا تُسْأَلُ عَنْ أَصْحَابِ الْجَحِيمِ", explication: "Nous t'avons envoyé avec la vérité, annonciateur et avertisseur. Tu ne seras pas interrogé sur les gens de l'Enfer." },
  { id: 120, arabic: "وَلَن تَرْضَىٰ عَنكَ الْيَهُودُ وَلَا النَّصَارَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمْ ۗ قُلْ إِنَّ هُدَى اللَّهِ هُوَ الْهُدَىٰ ۗ وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُم بَعْدَ الَّذِي جَاءَكَ مِنَ الْعِلْمِ ۙ مَا لَكَ مِنَ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ", explication: "Les Juifs et les Chrétiens ne seront jamais satisfaits de toi tant que tu ne suis pas leur religion. Dis : la guidance d'Allah est la vraie guidance." },
  { id: 121, arabic: "الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَتْلُونَهُ حَقَّ تِلَاوَتِهِ أُولَٰئِكَ يُؤْمِنُونَ بِهِ ۗ وَمَن يَكْفُرْ بِهِ فَأُولَٰئِكَ هُمُ الْخَاسِرُونَ", explication: "Ceux à qui Nous avons donné le Livre et qui le récitent comme il se doit, ceux-là y croient. Et quiconque le nie, ceux-là sont les perdants." },
  { id: 122, arabic: "يَا بَنِي إِسْرَائِيلَ اذْكُرُوا نِعْمَتِيَ الَّتِي أَنْعَمْتُ عَلَيْكُمْ وَأَنِّي فَضَّلْتُكُمْ عَلَى الْعَالَمِينَ", explication: "Ô Banû Isrâ'îl ! Rappelez-vous Mes bienfaits envers vous et que Je vous ai préférés aux mondes." },
  { id: 123, arabic: "وَاتَّقُوا يَوْمًا لَّا تَجْزِي نَفْسٌ عَن نَّفْسٍ شَيْئًا وَلَا يُقْبَلُ مِنْهَا عَدْلٌ وَلَا تَنفَعُهَا شَفَاعَةٌ وَلَا هُمْ يُنصَرُونَ", explication: "Craignez le Jour où nul ne servira de rien à un autre, nulle rançon ne sera acceptée, nulle intercession ne sera utile et ils ne seront pas secourus." },
  { id: 124, arabic: "وَإِذِ ابْتَلَىٰ إِبْرَاهِيمَ رَبُّهُ بِكَلِمَاتٍ فَأَتَمَّهُنَّ ۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامًا ۖ قَالَ وَمِن ذُرِّيَّتِي ۖ قَالَ لَا يَنَالُ عَهْدِي الظَّالِمِينَ", explication: "Quand son Seigneur éprouva Ibrahim par des commandements qu'il accomplit pleinement, Il dit : Je vais faire de toi un imam pour les gens. Il demanda pour sa descendance — Allah dit : Mon pacte n'atteint pas les injustes." },
  { id: 125, arabic: "وَإِذْ جَعَلْنَا الْبَيْتَ مَثَابَةً لِّلنَّاسِ وَأَمْنًا وَاتَّخِذُوا مِن مَّقَامِ إِبْرَاهِيمَ مُصَلًّى ۖ وَعَهِدْنَا إِلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ أَن طَهِّرَا بَيْتِيَ لِلطَّائِفِينَ وَالْعَاكِفِينَ وَالرُّكَّعِ السُّجُودِ", explication: "Nous avons fait de la Maison (Ka'ba) un lieu de rassemblement et de sécurité. Prenez la station d'Ibrahim comme lieu de prière. Nous avons commandé à Ibrahim et Ismaïl de purifier Ma Maison pour les circumambulants, les méditants et les prosternés." },
  { id: 126, arabic: "وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَٰذَا بَلَدًا آمِنًا وَارْزُقْ أَهْلَهُ مِنَ الثَّمَرَاتِ مَنْ آمَنَ مِنْهُم بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۖ قَالَ وَمَن كَفَرَ فَأُمَتِّعُهُ قَلِيلًا ثُمَّ أَضْطَرُّهُ إِلَىٰ عَذَابِ النَّارِ ۖ وَبِئْسَ الْمَصِيرُ", explication: "Ibrahim dit : Seigneur, fais de cette cité un lieu sûr et nourris ses habitants de fruits — ceux qui croient en Allah et au Jour dernier. Allah dit : J'accorderai à ceux qui mécroient une jouissance éphémère puis Je les entraînerai au Feu." },
  { id: 127, arabic: "وَإِذْ يَرْفَعُ إِبْرَاهِيمُ الْقَوَاعِدَ مِنَ الْبَيْتِ وَإِسْمَاعِيلُ رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ", explication: "Ibrahim et Ismaïl élevaient les fondations de la Maison en disant : Seigneur, accepte de nous. Tu es l'Audient, l'Omniscient." },
  { id: 128, arabic: "رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا ۖ إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ", explication: "Seigneur, fais de nous deux des soumis à Toi et de notre descendance une communauté soumise à Toi. Montre-nous nos rites et pardonne-nous. Tu es le Clément, le Miséricordieux." },
  { id: 129, arabic: "رَبَّنَا وَابْعَثْ فِيهِمْ رَسُولًا مِّنْهُمْ يَتْلُو عَلَيْهِمْ آيَاتِكَ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُزَكِّيهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ", explication: "Seigneur, envoie parmi eux un Messager d'eux qui leur lira Tes versets, leur enseignera le Livre et la Sagesse et les purifiera. Tu es le Puissant, le Sage." },
  { id: 130, arabic: "وَمَن يَرْغَبُ عَن مِّلَّةِ إِبْرَاهِيمَ إِلَّا مَن سَفِهَ نَفْسَهُ ۚ وَلَقَدِ اصْطَفَيْنَاهُ فِي الدُّنْيَا ۖ وَإِنَّهُ فِي الْآخِرَةِ لَمِنَ الصَّالِحِينَ", explication: "Qui se détournerait de la religion d'Ibrahim sinon qui s'avilit lui-même ? Nous l'avons élu en ce monde et dans l'au-delà il sera parmi les vertueux." },
  { id: 131, arabic: "إِذْ قَالَ لَهُ رَبُّهُ أَسْلِمْ ۖ قَالَ أَسْلَمْتُ لِرَبِّ الْعَالَمِينَ", explication: "Quand son Seigneur lui dit : soumets-toi ! Il dit : je me soumets au Seigneur des mondes." },
  { id: 132, arabic: "وَوَصَّىٰ بِهَا إِبْرَاهِيمُ بَنِيهِ وَيَعْقُوبُ يَا بَنِيَّ إِنَّ اللَّهَ اصْطَفَىٰ لَكُمُ الدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ", explication: "Ibrahim en fit l'héritage pour ses fils, et Jacob aussi : mes fils, Allah a choisi pour vous cette religion — ne mourez qu'en étant soumis à Lui." },
  { id: 133, arabic: "أَمْ كُنتُمْ شُهَدَاءَ إِذْ حَضَرَ يَعْقُوبَ الْمَوْتُ إِذْ قَالَ لِبَنِيهِ مَا تَعْبُدُونَ مِن بَعْدِي قَالُوا نَعْبُدُ إِلَٰهَكَ وَإِلَٰهَ آبَائِكَ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ إِلَٰهًا وَاحِدًا وَنَحْنُ لَهُ مُسْلِمُونَ", explication: "Étiez-vous présents quand Jacob fut sur le point de mourir et dit à ses fils : qu'adorerez-vous après moi ? Ils répondirent : ton Dieu et le Dieu de tes pères Ibrahim, Ismaïl et Ishaq — un Dieu unique — et nous Lui sommes soumis." },
  { id: 134, arabic: "تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْأَلُونَ عَمَّا كَانُوا يَعْمَلُونَ", explication: "Cette nation est passée. Elle a ce qu'elle a acquis et vous avez ce que vous avez acquis. Vous ne serez pas interrogés sur ce qu'ils faisaient." },
  { id: 135, arabic: "وَقَالُوا كُونُوا هُودًا أَوْ نَصَارَىٰ تَهْتَدُوا ۗ قُلْ بَلْ مِلَّةَ إِبْرَاهِيمَ حَنِيفًا ۖ وَمَا كَانَ مِنَ الْمُشْرِكِينَ", explication: "Ils ont dit : soyez Juifs ou Chrétiens pour être guidés. Dis : non, la religion d'Ibrahim le pur monothéiste — il n'était pas des polythéistes." },
  { id: 136, arabic: "قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَىٰ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَىٰ وَعِيسَىٰ وَمَا أُوتِيَ النَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ", explication: "Dites : nous croyons en Allah et en ce qui nous a été révélé, et en ce qui a été révélé à Ibrahim, Ismaïl, Ishaq, Jacob et les tribus, et à Moïse et Jésus. Nous ne faisons pas de distinction entre eux." },
  { id: 137, arabic: "فَإِنْ آمَنُوا بِمِثْلِ مَا آمَنتُم بِهِ فَقَدِ اهْتَدَوا ۖ وَّإِن تَوَلَّوْا فَإِنَّمَا هُمْ فِي شِقَاقٍ ۖ فَسَيَكْفِيكَهُمُ اللَّهُ ۚ وَهُوَ السَّمِيعُ الْعَلِيمُ", explication: "S'ils croient comme vous croyez, ils sont guidés. S'ils se détournent, ils sont dans le schisme. Allah te suffira contre eux. Il est l'Audient, l'Omniscient." },
  { id: 138, arabic: "صِبْغَةَ اللَّهِ ۖ وَمَنْ أَحْسَنُ مِنَ اللَّهِ صِبْغَةً ۖ وَنَحْنُ لَهُ عَابِدُونَ", explication: "La teinture d'Allah ! Et qui est meilleur qu'Allah pour teindre ? Et nous Lui sommes adorateurs." },
  { id: 139, arabic: "قُلْ أَتُحَاجُّونَنَا فِي اللَّهِ وَهُوَ رَبُّنَا وَرَبُّكُمْ وَلَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ وَنَحْنُ لَهُ مُخْلِصُونَ", explication: "Dis : voulez-vous nous disputer au sujet d'Allah, alors qu'Il est notre Seigneur et le vôtre ? Nous avons nos actes et vous avez les vôtres, et nous Lui sommes sincèrement dévoués." },
  { id: 140, arabic: "أَمْ تَقُولُونَ إِنَّ إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطَ كَانُوا هُودًا أَوْ نَصَارَىٰ ۗ قُلْ أَأَنتُمْ أَعْلَمُ أَمِ اللَّهُ ۗ وَمَنْ أَظْلَمُ مِمَّن كَتَمَ شَهَادَةً عِندَهُ مِنَ اللَّهِ ۗ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ", explication: "Dites-vous qu'Ibrahim, Ismaïl, Ishaq, Jacob et les tribus étaient Juifs ou Chrétiens ? Dis : êtes-vous plus savants ou Allah ? Qui est plus injuste que celui qui cache un témoignage qu'il détient d'Allah ?" },
  { id: 141, arabic: "تِلْكَ أُمَّةٌ قَدْ خَلَتْ ۖ لَهَا مَا كَسَبَتْ وَلَكُم مَّا كَسَبْتُمْ ۖ وَلَا تُسْأَلُونَ عَمَّا كَانُوا يَعْمَلُونَ", explication: "Cette nation est passée. Elle a ce qu'elle a acquis et vous avez ce que vous avez acquis. Vous ne serez pas interrogés sur ce qu'ils faisaient." },
  { id: 142, arabic: "سَيَقُولُ السُّفَهَاءُ مِنَ النَّاسِ مَا وَلَّاهُمْ عَن قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا ۚ قُل لِّلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ ۚ يَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ", explication: "Les sots parmi les gens diront : qu'est-ce qui les a détournés de leur ancienne Qibla ? Dis : à Allah appartiennent l'Orient et l'Occident. Il guide qui Il veut vers un chemin droit." },
  { id: 143, arabic: "وَكَذَٰلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا ۗ وَمَا جَعَلْنَا الْقِبْلَةَ الَّتِي كُنتَ عَلَيْهَا إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ الرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ ۚ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى الَّذِينَ هَدَى اللَّهُ ۗ وَمَا كَانَ اللَّهُ لِيُضِيعَ إِيمَانَكُمْ ۚ إِنَّ اللَّهَ بِالنَّاسِ لَرَءُوفٌ رَّحِيمٌ", explication: "Nous vous avons faits une communauté du juste milieu pour être témoins sur les gens et que le Messager soit témoin sur vous. Nous n'avions établi l'ancienne Qibla que pour distinguer qui suivrait le Messager." },
  { id: 144, arabic: "قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ ۖ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا ۚ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ ۗ وَإِنَّ الَّذِينَ أُوتُوا الْكِتَابَ لَيَعْلَمُونَ أَنَّهُ الْحَقُّ مِن رَّبِّهِمْ ۗ وَمَا اللَّهُ بِغَافِلٍ عَمَّا يَعْمَلُونَ", explication: "Nous voyons ton visage se tourner vers le ciel — Nous allons t'orienter vers une Qibla qui te plaise. Tourne ton visage vers la Mosquée Sacrée. Où que vous soyez, tournez-y vos visages." },
  { id: 145, arabic: "وَلَئِنْ أَتَيْتَ الَّذِينَ أُوتُوا الْكِتَابَ بِكُلِّ آيَةٍ مَّا تَبِعُوا قِبْلَتَكَ ۚ وَمَا أَنتَ بِتَابِعٍ قِبْلَتَهُمْ ۚ وَمَا بَعْضُهُم بِتَابِعٍ قِبْلَةَ بَعْضٍ ۚ وَلَئِنِ اتَّبَعْتَ أَهْوَاءَهُم مِّن بَعْدِ مَا جَاءَكَ مِنَ الْعِلْمِ ۙ إِنَّكَ إِذًا لَّمِنَ الظَّالِمِينَ", explication: "Si tu apportais aux Gens du Livre toutes les preuves, ils ne suivraient pas ta Qibla, et tu ne suis pas la leur. Et si tu suivais leurs caprices après la science qui t'est venue, tu serais des injustes." },
  { id: 146, arabic: "الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ ۖ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ", explication: "Ceux à qui Nous avons donné le Livre le reconnaissent comme leurs propres fils. Et certes un groupe d'entre eux cache la vérité en sachant." },
  { id: 147, arabic: "الْحَقُّ مِن رَّبِّكَ ۖ فَلَا تَكُونَنَّ مِنَ الْمُمْتَرِينَ", explication: "La vérité vient de ton Seigneur — ne sois pas des dubitatifs." },
  { id: 148, arabic: "وَلِكُلٍّ وِجْهَةٌ هُوَ مُوَلِّيهَا ۖ فَاسْتَبِقُوا الْخَيْرَاتِ ۚ أَيْنَ مَا تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعًا ۚ إِنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", explication: "Chacun a une direction vers laquelle il se tourne. Rivalisez donc dans les bonnes œuvres. Où que vous soyez, Allah vous réunira. Il est Puissant sur toute chose." },
  { id: 149, arabic: "وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ ۖ وَإِنَّهُ لَلْحَقُّ مِن رَّبِّكَ ۗ وَمَا اللَّهُ بِغَافِلٍ عَمَّا تَعْمَلُونَ", explication: "D'où que tu sortes, tourne ton visage vers la Mosquée Sacrée. C'est la vérité de ton Seigneur." },
  { id: 150, arabic: "وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَيْكُمْ حُجَّةٌ إِلَّا الَّذِينَ ظَلَمُوا مِنْهُمْ فَلَا تَخْشَوْهُمْ وَاخْشَوْنِي وَلِأُتِمَّ نِعْمَتِي عَلَيْكُمْ وَلَعَلَّكُمْ تَهْتَدُونَ", explication: "D'où que tu sortes, tourne-toi vers la Mosquée Sacrée, afin que les gens n'aient pas d'argument contre vous. Ne les craignez pas mais craignez-Moi, pour que Je complète Mon bienfait sur vous." },
  { id: 151, arabic: "كَمَا أَرْسَلْنَا فِيكُمْ رَسُولًا مِّنكُمْ يَتْلُو عَلَيْكُمْ آيَاتِنَا وَيُزَكِّيكُمْ وَيُعَلِّمُكُمُ الْكِتَابَ وَالْحِكْمَةَ وَيُعَلِّمُكُم مَّا لَمْ تَكُونُوا تَعْلَمُونَ", explication: "De même que Nous vous avons envoyé un Messager d'entre vous qui vous récite Nos versets, vous purifie, vous enseigne le Livre, la Sagesse et ce que vous ne saviez pas." },
  { id: 152, arabic: "فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُوا لِي وَلَا تَكْفُرُونِ", explication: "Rappelez-Moi, Je vous rappellerai. Soyez reconnaissants envers Moi et ne soyez pas ingrats." },
  { id: 153, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ ۚ إِنَّ اللَّهَ مَعَ الصَّابِرِينَ", explication: "Ô croyants ! Cherchez secours dans la patience et la prière. Allah est avec les patients." },
  { id: 154, arabic: "وَلَا تَقُولُوا لِمَن يُقْتَلُ فِي سَبِيلِ اللَّهِ أَمْوَاتٌ ۚ بَلْ أَحْيَاءٌ وَلَٰكِن لَّا تَشْعُرُونَ", explication: "Ne dites pas de ceux qui sont tués dans le chemin d'Allah : ils sont morts. Non ! Ils sont vivants, mais vous ne le percevez pas." },
  { id: 155, arabic: "وَلَنَبْلُوَنَّكُم بِشَيْءٍ مِّنَ الْخَوْفِ وَالْجُوعِ وَنَقْصٍ مِّنَ الْأَمْوَالِ وَالْأَنفُسِ وَالثَّمَرَاتِ ۗ وَبَشِّرِ الصَّابِرِينَ", explication: "Nous vous éprouverons d'un peu de crainte, de faim, de pertes en biens, en vies et en fruits. Annonce la bonne nouvelle aux patients." },
  { id: 156, arabic: "الَّذِينَ إِذَا أَصَابَتْهُم مُّصِيبَةٌ قَالُوا إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ", explication: "Ceux qui, quand un malheur les frappe, disent : nous appartenons à Allah et c'est vers Lui que nous retournons." },
  { id: 157, arabic: "أُولَٰئِكَ عَلَيْهِمْ صَلَوَاتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ ۖ وَأُولَٰئِكَ هُمُ الْمُهْتَدُونَ", explication: "Ceux-là recevront les bénédictions de leur Seigneur et Sa miséricorde, et ce sont eux les bien guidés." },
  { id: 158, arabic: "إِنَّ الصَّفَا وَالْمَرْوَةَ مِن شَعَائِرِ اللَّهِ ۖ فَمَنْ حَجَّ الْبَيْتَ أَوِ اعْتَمَرَ فَلَا جُنَاحَ عَلَيْهِ أَن يَطَّوَّفَ بِهِمَا ۚ وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ", explication: "Safa et Marwa font partie des rites d'Allah. Celui qui fait le Pèlerinage ou la 'Umra n'a pas de péché à faire la sa'y entre les deux. Quiconque fait une bonne œuvre de son propre gré — Allah est Reconnaissant, Omniscient." },
  { id: 159, arabic: "إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَىٰ مِن بَعْدِ مَا بَيَّنَّاهُ لِلنَّاسِ فِي الْكِتَابِ ۙ أُولَٰئِكَ يَلْعَنُهُمُ اللَّهُ وَيَلْعَنُهُمُ اللَّاعِنُونَ", explication: "Ceux qui cachent ce que Nous avons révélé comme preuves et guidance, après que Nous l'avons clarifié — Allah les maudit et les maudisseurs les maudissent." },
  { id: 160, arabic: "إِلَّا الَّذِينَ تَابُوا وَأَصْلَحُوا وَبَيَّنُوا فَأُولَٰئِكَ أَتُوبُ عَلَيْهِمْ ۚ وَأَنَا التَّوَّابُ الرَّحِيمُ", explication: "Sauf ceux qui se repentent, se réforment et déclarent la vérité — ceux-là Je leur pardonne. Je suis le Clément, le Miséricordieux." },
  { id: 161, arabic: "إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ أُولَٰئِكَ عَلَيْهِمْ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ وَالنَّاسِ أَجْمَعِينَ", explication: "Ceux qui mécroient et meurent dans la mécréance — sur eux la malédiction d'Allah, des anges et de toute l'humanité." },
  { id: 162, arabic: "خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ", explication: "Ils y demeureront éternellement. Le châtiment ne leur sera pas allégé et ils n'auront pas de répit." },
  { id: 163, arabic: "وَإِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ ۖ لَّا إِلَٰهَ إِلَّا هُوَ الرَّحْمَٰنُ الرَّحِيمُ", explication: "Votre Dieu est un Dieu unique. Pas de divinité sauf Lui, le Tout Miséricordieux, le Très Miséricordieux." },
  { id: 164, arabic: "إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ وَالْفُلْكِ الَّتِي تَجْرِي فِي الْبَحْرِ بِمَا يَنفَعُ النَّاسَ وَمَا أَنزَلَ اللَّهُ مِنَ السَّمَاءِ مِن مَّاءٍ فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَابَّةٍ وَتَصْرِيفِ الرِّيَاحِ وَالسَّحَابِ الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالْأَرْضِ لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ", explication: "Dans la création des cieux et de la terre, l'alternance du jour et de la nuit, les navires qui voguent en mer, la pluie qui vivifie la terre morte, les vents et les nuages — il y a des signes pour ceux qui raisonnent." },
  { id: 165, arabic: "وَمِنَ النَّاسِ مَن يَتَّخِذُ مِن دُونِ اللَّهِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ اللَّهِ ۖ وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِّلَّهِ ۗ وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذَابَ أَنَّ الْقُوَّةَ لِلَّهِ جَمِيعًا وَأَنَّ اللَّهَ شَدِيدُ الْعَذَابِ", explication: "Il y a des gens qui prennent des égaux à Allah et les aiment comme on aime Allah. Mais les croyants aiment Allah plus intensément. Si les injustes voyaient le châtiment, ils sauraient que la puissance appartient entièrement à Allah." },
  { id: 166, arabic: "إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا وَرَأَوُا الْعَذَابَ وَتَقَطَّعَتْ بِهِمُ الْأَسْبَابُ", explication: "Quand les chefs se dissocieront de leurs suivants au vu du châtiment, et que les liens seront rompus entre eux." },
  { id: 167, arabic: "وَقَالَ الَّذِينَ اتَّبَعُوا لَوْ أَنَّ لَنَا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا مِنَّا ۗ كَذَٰلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ ۖ وَمَا هُم بِخَارِجِينَ مِنَ النَّارِ", explication: "Les suivants diront : si seulement nous pouvions recommencer pour nous dissocier d'eux comme ils se sont dissociés de nous ! Allah leur montrera leurs œuvres comme regrets, et ils ne sortiront pas du Feu." },
  { id: 168, arabic: "يَا أَيُّهَا النَّاسُ كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ ۚ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ", explication: "Ô humanité ! Mangez ce qui est licite et bon sur la terre et ne suivez pas les traces du Diable. Il est pour vous un ennemi déclaré." },
  { id: 169, arabic: "إِنَّمَا يَأْمُرُكُم بِالسُّوءِ وَالْفَحْشَاءِ وَأَن تَقُولُوا عَلَى اللَّهِ مَا لَا تَعْلَمُونَ", explication: "Il vous ordonne seulement le mal et l'infâme, et de dire sur Allah ce que vous ne savez pas." },
  { id: 170, arabic: "وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا ۗ أَوَلَوْ كَانَ آبَاؤُهُمْ لَا يَعْقِلُونَ شَيْئًا وَلَا يَهْتَدُونَ", explication: "Quand on leur dit de suivre ce qu'Allah a révélé, ils disent qu'ils suivent ce qu'ils ont trouvé chez leurs pères — même si leurs pères ne raisonnaient pas et n'étaient pas guidés ?" },
  { id: 171, arabic: "وَمَثَلُ الَّذِينَ كَفَرُوا كَمَثَلِ الَّذِي يَنْعِقُ بِمَا لَا يَسْمَعُ إِلَّا دُعَاءً وَنِدَاءً ۚ صُمٌّ بُكْمٌ عُمْيٌ فَهُمْ لَا يَعْقِلُونَ", explication: "L'exemple des mécréants est comme celui qui crie après ce qui n'entend qu'un appel. Sourds, muets, aveugles — ils ne raisonnent pas." },
  { id: 172, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا كُلُوا مِن طَيِّبَاتِ مَا رَزَقْنَاكُمْ وَاشْكُرُوا لِلَّهِ إِن كُنتُمْ إِيَّاهُ تَعْبُدُونَ", explication: "Ô croyants ! Mangez des bonnes choses que Nous vous avons accordées et soyez reconnaissants envers Allah si c'est Lui que vous adorez." },
  { id: 173, arabic: "إِنَّمَا حَرَّمَ عَلَيْكُمُ الْمَيْتَةَ وَالدَّمَ وَلَحْمَ الْخِنزِيرِ وَمَا أُهِلَّ بِهِ لِغَيْرِ اللَّهِ ۖ فَمَنِ اضْطُرَّ غَيْرَ بَاغٍ وَلَا عَادٍ فَلَا إِثْمَ عَلَيْهِ ۚ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ", explication: "Il ne vous a interdit que la charogne, le sang, la chair de porc et ce sur quoi un autre nom qu'Allah a été invoqué. Mais en cas de nécessité sans désir ni excès, pas de péché. Allah est Pardonneur, Miséricordieux." },
  { id: 174, arabic: "إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنزَلَ اللَّهُ مِنَ الْكِتَابِ وَيَشْتَرُونَ بِهِ ثَمَنًا قَلِيلًا ۙ أُولَٰئِكَ مَا يَأْكُلُونَ فِي بُطُونِهِمْ إِلَّا النَّارَ وَلَا يُكَلِّمُهُمُ اللَّهُ يَوْمَ الْقِيَامَةِ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ", explication: "Ceux qui cachent ce qu'Allah a révélé dans le Livre et en tirent un vil profit — ceux-là n'ingurgitent dans leurs ventres que le Feu. Allah ne leur parlera pas au Jour du Jugement." },
  { id: 175, arabic: "أُولَٰئِكَ الَّذِينَ اشْتَرَوُا الضَّلَالَةَ بِالْهُدَىٰ وَالْعَذَابَ بِالْمَغْفِرَةِ ۚ فَمَا أَصْبَرَهُمْ عَلَى النَّارِ", explication: "Ceux-là ont échangé la guidance contre l'égarement et le pardon contre le châtiment. Qu'ils sont endurants face au Feu !" },
  { id: 176, arabic: "ذَٰلِكَ بِأَنَّ اللَّهَ نَزَّلَ الْكِتَابَ بِالْحَقِّ ۗ وَإِنَّ الَّذِينَ اخْتَلَفُوا فِي الْكِتَابِ لَفِي شِقَاقٍ بَعِيدٍ", explication: "Cela parce qu'Allah a révélé le Livre avec la vérité. Ceux qui divergent à propos du Livre sont dans un profond schisme." },
  { id: 177, arabic: "لَّيْسَ الْبِرَّ أَن تُوَلُّوا وُجُوهَكُمْ قِبَلَ الْمَشْرِقِ وَالْمَغْرِبِ وَلَٰكِنَّ الْبِرَّ مَنْ آمَنَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَالْمَلَائِكَةِ وَالْكِتَابِ وَالنَّبِيِّينَ وَآتَى الْمَالَ عَلَىٰ حُبِّهِ ذَوِي الْقُرْبَىٰ وَالْيَتَامَىٰ وَالْمَسَاكِينَ وَابْنَ السَّبِيلِ وَالسَّائِلِينَ وَفِي الرِّقَابِ وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ وَالْمُوفُونَ بِعَهْدِهِمْ إِذَا عَاهَدُوا ۖ وَالصَّابِرِينَ فِي الْبَأْسَاءِ وَالضَّرَّاءِ وَحِينَ الْبَأْسِ ۗ أُولَٰئِكَ الَّذِينَ صَدَقُوا ۖ وَأُولَٰئِكَ هُمُ الْمُتَّقُونَ", explication: "La piété n'est pas de tourner son visage vers l'Orient ou l'Occident. La vraie piété c'est croire en Allah, au Jour Dernier, aux anges, au Livre et aux prophètes, et donner aux proches, orphelins, pauvres, voyageurs, mendiants, et pour les esclaves, accomplir la prière et la Zakât." },
  { id: 178, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الْقِصَاصُ فِي الْقَتْلَى ۖ الْحُرُّ بِالْحُرِّ وَالْعَبْدُ بِالْعَبْدِ وَالْأُنثَىٰ بِالْأُنثَىٰ ۚ فَمَنْ عُفِيَ لَهُ مِنْ أَخِيهِ شَيْءٌ فَاتِّبَاعٌ بِالْمَعْرُوفِ وَأَدَاءٌ إِلَيْهِ بِإِحْسَانٍ ۗ ذَٰلِكَ تَخْفِيفٌ مِّن رَّبِّكُمْ وَرَحْمَةٌ ۗ فَمَنِ اعْتَدَىٰ بَعْدَ ذَٰلِكَ فَلَهُ عَذَابٌ أَلِيمٌ", explication: "Ô croyants ! Le talion vous est prescrit pour les meurtres. Mais si on lui remet quelque chose (diyah), qu'il soit suivi convenablement et payé avec bonté. C'est un allègement et une miséricorde de votre Seigneur." },
  { id: 179, arabic: "وَلَكُمْ فِي الْقِصَاصِ حَيَاةٌ يَا أُولِي الْأَلْبَابِ لَعَلَّكُمْ تَتَّقُونَ", explication: "Il y a pour vous une vie dans le talion, ô gens de réflexion ! Peut-être serez-vous pieux." },
  { id: 180, arabic: "كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِن تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ ۖ حَقًّا عَلَى الْمُتَّقِينَ", explication: "Il vous est prescrit, quand la mort approche l'un d'entre vous et qu'il laisse des biens, de léguer équitablement à ses parents et proches. C'est un devoir pour les pieux." },
  { id: 181, arabic: "فَمَن بَدَّلَهُ بَعْدَمَا سَمِعَهُ فَإِنَّمَا إِثْمُهُ عَلَى الَّذِينَ يُبَدِّلُونَهُ ۚ إِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ", explication: "Quiconque le modifie après l'avoir entendu, le péché n'en retombera que sur ceux qui le modifient. Allah est Audient, Omniscient." },
  { id: 182, arabic: "فَمَنْ خَافَ مِن مُّوصٍ جَنَفًا أَوْ إِثْمًا فَأَصْلَحَ بَيْنَهُمْ فَلَا إِثْمَ عَلَيْهِ ۚ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ", explication: "Si quelqu'un craint que le testateur soit partial ou fasse une injustice et qu'il arrange les choses entre les parties, pas de péché pour lui. Allah est Pardonneur, Miséricordieux." },
  { id: 183, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ", explication: "Ô croyants ! Le jeûne vous est prescrit comme il l'a été à ceux d'avant vous — peut-être serez-vous pieux." },
  { id: 184, arabic: "أَيَّامًا مَّعْدُودَاتٍ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۚ وَعَلَى الَّذِينَ يُطِيقُونَهُ فِدْيَةٌ طَعَامُ مِسْكِينٍ ۖ فَمَن تَطَوَّعَ خَيْرًا فَهُوَ خَيْرٌ لَّهُ ۚ وَأَن تَصُومُوا خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ", explication: "Des jours comptés. Celui qui est malade ou en voyage jeûnera un nombre équivalent d'autres jours. Et pour ceux qui peuvent le faire, la fidya est de nourrir un pauvre. Le jeûne est meilleur pour vous si vous saviez." },
  { id: 185, arabic: "شَهْرُ رَمَضَانَ الَّذِي أُنزِلَ فِيهِ الْقُرْآنُ هُدًى لِّلنَّاسِ وَبَيِّنَاتٍ مِّنَ الْهُدَىٰ وَالْفُرْقَانِ ۚ فَمَن شَهِدَ مِنكُمُ الشَّهْرَ فَلْيَصُمْهُ ۖ وَمَن كَانَ مَرِيضًا أَوْ عَلَىٰ سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ ۗ يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ وَلَا يُرِيدُ بِكُمُ الْعُسْرَ وَلِتُكْمِلُوا الْعِدَّةَ وَلِتُكَبِّرُوا اللَّهَ عَلَىٰ مَا هَدَاكُمْ وَلَعَلَّكُمْ تَشْكُرُونَ", explication: "Le mois de Ramadan pendant lequel le Coran a été révélé, guide pour les gens et clarté. Quiconque est présent ce mois doit le jeûner. Allah veut la facilité pour vous, non la difficulté." },
  { id: 186, arabic: "وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ", explication: "Quand Mes serviteurs t'interrogent sur Moi — Je suis proche. Je réponds à l'appel de celui qui M'appelle. Qu'ils répondent à Mon appel et qu'ils croient en Moi — peut-être seront-ils guidés." },
  { id: 187, arabic: "أُحِلَّ لَكُمْ لَيْلَةَ الصِّيَامِ الرَّفَثُ إِلَىٰ نِسَائِكُمْ ۚ هُنَّ لِبَاسٌ لَّكُمْ وَأَنتُمْ لِبَاسٌ لَّهُنَّ ۗ عَلِمَ اللَّهُ أَنَّكُمْ كُنتُمْ تَخْتَانُونَ أَنفُسَكُمْ فَتَابَ عَلَيْكُمْ وَعَفَا عَنكُمْ ۖ فَالْآنَ بَاشِرُوهُنَّ وَابْتَغُوا مَا كَتَبَ اللَّهُ لَكُمْ ۚ وَكُلُوا وَاشْرَبُوا حَتَّىٰ يَتَبَيَّنَ لَكُمُ الْخَيْطُ الْأَبْيَضُ مِنَ الْخَيْطِ الْأَسْوَدِ مِنَ الْفَجْرِ ۖ ثُمَّ أَتِمُّوا الصِّيَامَ إِلَى اللَّيْلِ", explication: "Il vous est permis la nuit du jeûne d'approcher vos épouses. Elles sont un vêtement pour vous et vous l'êtes pour elles. Mangez et buvez jusqu'à ce que le fil blanc du fil noir de l'aube se distingue, puis complétez le jeûne jusqu'à la nuit." },
  { id: 188, arabic: "وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ وَتُدْلُوا بِهَا إِلَى الْحُكَّامِ لِتَأْكُلُوا فَرِيقًا مِّنْ أَمْوَالِ النَّاسِ بِالْإِثْمِ وَأَنتُمْ تَعْلَمُونَ", explication: "Ne dévorez pas vos biens mutuellement de façon injuste et ne les soumettez pas aux juges pour vous emparer illicitement d'une partie des biens d'autrui, le sachant." },
  { id: 189, arabic: "يَسْأَلُونَكَ عَنِ الْأَهِلَّةِ ۖ قُلْ هِيَ مَوَاقِيتُ لِلنَّاسِ وَالْحَجِّ ۗ وَلَيْسَ الْبِرُّ بِأَن تَأْتُوا الْبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ الْبِرَّ مَنِ اتَّقَىٰ ۗ وَأْتُوا الْبُيُوتَ مِنْ أَبْوَابِهَا ۚ وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ", explication: "On t'interroge sur les croissants de lune. Dis : ce sont des repères de temps pour les gens et le Pèlerinage. La vraie piété n'est pas d'entrer dans les maisons par derrière." },
  { id: 190, arabic: "وَقَاتِلُوا فِي سَبِيلِ اللَّهِ الَّذِينَ يُقَاتِلُونَكُمْ وَلَا تَعْتَدُوا ۚ إِنَّ اللَّهَ لَا يُحِبُّ الْمُعْتَدِينَ", explication: "Combattez dans le chemin d'Allah ceux qui vous combattent, mais ne transgressez pas. Allah n'aime pas les transgresseurs." },
  { id: 191, arabic: "وَاقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ وَأَخْرِجُوهُم مِّنْ حَيْثُ أَخْرَجُوكُمْ ۚ وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ ۚ وَلَا تُقَاتِلُوهُمْ عِندَ الْمَسْجِدِ الْحَرَامِ حَتَّىٰ يُقَاتِلُوكُمْ فِيهِ ۖ فَإِن قَاتَلُوكُمْ فَاقْتُلُوهُمْ ۗ كَذَٰلِكَ جَزَاءُ الْكَافِرِينَ", explication: "Tuez-les où que vous les trouviez et chassez-les d'où ils vous ont chassés. La fitna est plus grave que le meurtre. Ne les combattez pas près de la Mosquée Sacrée à moins qu'ils ne vous y combattent." },
  { id: 192, arabic: "فَإِنِ انتَهَوْا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ", explication: "S'ils s'arrêtent, alors Allah est Pardonneur, Miséricordieux." },
  { id: 193, arabic: "وَقَاتِلُوهُمْ حَتَّىٰ لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ لِلَّهِ ۖ فَإِنِ انتَهَوْا فَلَا عُدْوَانَ إِلَّا عَلَى الظَّالِمِينَ", explication: "Combattez-les jusqu'à ce qu'il n'y ait plus de fitna et que la religion soit à Allah. S'ils s'arrêtent, plus d'hostilités sinon contre les injustes." },
  { id: 194, arabic: "الشَّهْرُ الْحَرَامُ بِالشَّهْرِ الْحَرَامِ وَالْحُرُمَاتُ قِصَاصٌ ۚ فَمَنِ اعْتَدَىٰ عَلَيْكُمْ فَاعْتَدُوا عَلَيْهِ بِمِثْلِ مَا اعْتَدَىٰ عَلَيْكُمْ ۚ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ مَعَ الْمُتَّقِينَ", explication: "Le mois sacré pour le mois sacré. Les choses sacrées appellent représailles. Quiconque vous agresse, agresse-le de même. Craignez Allah et sachez qu'Il est avec les pieux." },
  { id: 195, arabic: "وَأَنفِقُوا فِي سَبِيلِ اللَّهِ وَلَا تُلْقُوا بِأَيْدِيكُمْ إِلَى التَّهْلُكَةِ ۛ وَأَحْسِنُوا ۛ إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ", explication: "Dépensez dans le chemin d'Allah et ne vous précipitez pas vers la perdition. Faites le bien ! Allah aime les bienfaisants." },
  { id: 196, arabic: "وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ ۚ فَإِنْ أُحْصِرْتُمْ فَمَا اسْتَيْسَرَ مِنَ الْهَدْيِ ۖ وَلَا تَحْلِقُوا رُءُوسَكُمْ حَتَّىٰ يَبْلُغَ الْهَدْيُ مَحِلَّهُ ۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوْ بِهِ أَذًى مِّن رَّأْسِهِ فَفِدْيَةٌ مِّن صِيَامٍ أَوْ صَدَقَةٍ أَوْ نُسُكٍ", explication: "Accomplissez le Pèlerinage et la 'Umra pour Allah. Si vous en êtes empêchés, offrez ce qui est possible comme sacrifice." },
  { id: 197, arabic: "الْحَجُّ أَشْهُرٌ مَّعْلُومَاتٌ ۚ فَمَن فَرَضَ فِيهِنَّ الْحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي الْحَجِّ ۗ وَمَا تَفْعَلُوا مِنْ خَيْرٍ يَعْلَمْهُ اللَّهُ ۗ وَتَزَوَّدُوا فَإِنَّ خَيْرَ الزَّادِ التَّقْوَىٰ ۚ وَاتَّقُونِ يَا أُولِي الْأَلْبَابِ", explication: "Le Pèlerinage se fait en des mois connus. Pas de rapports conjugaux, pas d'actes pervers ni de querelles pendant le Pèlerinage. Le meilleur viatique est la piété." },
  { id: 198, arabic: "لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَبْتَغُوا فَضْلًا مِّن رَّبِّكُمْ ۚ فَإِذَا أَفَضْتُم مِّنْ عَرَفَاتٍ فَاذْكُرُوا اللَّهَ عِندَ الْمَشْعَرِ الْحَرَامِ ۖ وَاذْكُرُوهُ كَمَا هَدَاكُمْ وَإِن كُنتُم مِّن قَبْلِهِ لَمِنَ الضَّالِّينَ", explication: "Pas de péché à chercher la grâce de votre Seigneur (commerce). Quand vous défluez d'Arafa, évoquez Allah au Mash'ar Al-Harâm et évoquez-Le comme Il vous a guidés." },
  { id: 199, arabic: "ثُمَّ أَفِيضُوا مِنْ حَيْثُ أَفَاضَ النَّاسُ وَاسْتَغْفِرُوا اللَّهَ ۚ إِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ", explication: "Puis défluez d'où les gens défluent et demandez pardon à Allah. Il est Pardonneur, Miséricordieux." },
  { id: 200, arabic: "فَإِذَا قَضَيْتُم مَّنَاسِكَكُمْ فَاذْكُرُوا اللَّهَ كَذِكْرِكُمْ آبَاءَكُمْ أَوْ أَشَدَّ ذِكْرًا ۗ فَمِنَ النَّاسِ مَن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا وَمَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ", explication: "Quand vous avez accompli vos rites, évoquez Allah comme vous évoquiez vos ancêtres, ou même plus intensément. Il y a des gens qui ne demandent que les biens de ce monde, sans part dans l'au-delà." },
  { id: 201, arabic: "وَمِنْهُم مَّن يَقُولُ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ", explication: "Et parmi eux, il y en a qui disent : Seigneur, accorde-nous le bien en ce monde et le bien dans l'au-delà et préserve-nous du châtiment du Feu." },
  { id: 202, arabic: "أُولَٰئِكَ لَهُمْ نَصِيبٌ مِّمَّا كَسَبُوا ۚ وَاللَّهُ سَرِيعُ الْحِسَابِ", explication: "Ceux-là auront leur part de ce qu'ils ont acquis. Allah est prompt dans le compte." },
  { id: 203, arabic: "وَاذْكُرُوا اللَّهَ فِي أَيَّامٍ مَّعْدُودَاتٍ ۚ فَمَن تَعَجَّلَ فِي يَوْمَيْنِ فَلَا إِثْمَ عَلَيْهِ وَمَن تَأَخَّرَ فَلَا إِثْمَ عَلَيْهِ ۚ لِمَنِ اتَّقَىٰ ۗ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّكُمْ إِلَيْهِ تُحْشَرُونَ", explication: "Évoquez Allah pendant les jours comptés. Qui se hâte en deux jours n'a pas de péché, et qui reste pas non plus — pour celui qui craint Allah. Sachez que vous serez rassemblés vers Lui." },
  { id: 204, arabic: "وَمِنَ النَّاسِ مَن يُعْجِبُكَ قَوْلُهُ فِي الْحَيَاةِ الدُّنْيَا وَيُشْهِدُ اللَّهَ عَلَىٰ مَا فِي قَلْبِهِ وَهُوَ أَلَدُّ الْخِصَامِ", explication: "Il y a des gens dont le discours sur la vie d'ici-bas t'émerveille et qui prennent Allah à témoin de ce qu'ils ont dans le cœur — alors qu'ils sont les plus chicaneurs." },
  { id: 205, arabic: "وَإِذَا تَوَلَّىٰ سَعَىٰ فِي الْأَرْضِ لِيُفْسِدَ فِيهَا وَيُهْلِكَ الْحَرْثَ وَالنَّسْلَ ۗ وَاللَّهُ لَا يُحِبُّ الْفَسَادَ", explication: "Dès qu'il se retourne, il court la terre pour y semer la corruption et détruire les cultures et le bétail. Allah n'aime pas la corruption." },
  { id: 206, arabic: "وَإِذَا قِيلَ لَهُ اتَّقِ اللَّهَ أَخَذَتْهُ الْعِزَّةُ بِالْإِثْمِ ۚ فَحَسْبُهُ جَهَنَّمُ ۚ وَلَبِئْسَ الْمِهَادُ", explication: "Quand on lui dit : crains Allah, l'orgueil le saisit dans le péché. L'Enfer lui suffira — quelle détestable couche !" },
  { id: 207, arabic: "وَمِنَ النَّاسِ مَن يَشْرِي نَفْسَهُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ ۗ وَاللَّهُ رَءُوفٌ بِالْعِبَادِ", explication: "Et il y a des gens qui se sacrifient pour la satisfaction d'Allah. Allah est Bienveillant envers Ses serviteurs." },
  { id: 208, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا ادْخُلُوا فِي السِّلْمِ كَافَّةً وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ ۚ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ", explication: "Ô croyants ! Entrez tous dans la paix (l'Islam) et ne suivez pas les traces du Diable. Il est pour vous un ennemi déclaré." },
  { id: 209, arabic: "فَإِن زَلَلْتُم مِّن بَعْدِ مَا جَاءَتْكُمُ الْبَيِّنَاتُ فَاعْلَمُوا أَنَّ اللَّهَ عَزِيزٌ حَكِيمٌ", explication: "Si vous dérapez après que des preuves claires vous sont venues, sachez qu'Allah est Puissant, Sage." },
  { id: 210, arabic: "هَلْ يَنظُرُونَ إِلَّا أَن يَأْتِيَهُمُ اللَّهُ فِي ظُلَلٍ مِّنَ الْغَمَامِ وَالْمَلَائِكَةُ وَقُضِيَ الْأَمْرُ ۚ وَإِلَى اللَّهِ تُرْجَعُ الْأُمُورُ", explication: "N'attendent-ils que l'avènement d'Allah parmi les nuages avec les anges, quand l'affaire sera décidée ? Vers Allah tout retourne." },
  { id: 211, arabic: "سَلْ بَنِي إِسْرَائِيلَ كَمْ آتَيْنَاهُم مِّنْ آيَةٍ بَيِّنَةٍ ۗ وَمَن يُبَدِّلْ نِعْمَةَ اللَّهِ مِن بَعْدِ مَا جَاءَتْهُ فَإِنَّ اللَّهَ شَدِيدُ الْعِقَابِ", explication: "Demande aux Banû Isrâ'îl combien de signes évidents Nous leur avons donnés. Quiconque change le bienfait d'Allah après qu'il lui est venu — Allah est sévère dans le châtiment." },
  { id: 212, arabic: "زُيِّنَ لِلَّذِينَ كَفَرُوا الْحَيَاةُ الدُّنْيَا وَيَسْخَرُونَ مِنَ الَّذِينَ آمَنُوا ۘ وَالَّذِينَ اتَّقَوْا فَوْقَهُمْ يَوْمَ الْقِيَامَةِ ۗ وَاللَّهُ يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ", explication: "La vie d'ici-bas a été embellie aux yeux des mécréants qui se moquent des croyants. Mais les pieux seront au-dessus d'eux le Jour du Jugement. Allah pourvoit sans compter à qui Il veut." },
  { id: 213, arabic: "كَانَ النَّاسُ أُمَّةً وَاحِدَةً فَبَعَثَ اللَّهُ النَّبِيِّينَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ الْكِتَابَ بِالْحَقِّ لِيَحْكُمَ بَيْنَ النَّاسِ فِيمَا اخْتَلَفُوا فِيهِ ۚ وَمَا اخْتَلَفَ فِيهِ إِلَّا الَّذِينَ أُوتُوهُ مِن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَاتُ بَغْيًا بَيْنَهُمْ ۖ فَهَدَى اللَّهُ الَّذِينَ آمَنُوا لِمَا اخْتَلَفُوا فِيهِ مِنَ الْحَقِّ بِإِذْنِهِ ۗ وَاللَّهُ يَهْدِي مَن يَشَاءُ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ", explication: "Les gens étaient une seule communauté. Allah a envoyé des prophètes annonciateurs et avertisseurs, et révélé avec eux le Livre pour juger entre eux. Allah a guidé les croyants vers la vérité." },
  { id: 214, arabic: "أَمْ حَسِبْتُمْ أَن تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ الَّذِينَ خَلَوْا مِن قَبْلِكُم ۖ مَّسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ وَزُلْزِلُوا حَتَّىٰ يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتَىٰ نَصْرُ اللَّهِ ۗ أَلَا إِنَّ نَصْرَ اللَّهِ قَرِيبٌ", explication: "Pensez-vous entrer au Paradis sans avoir été éprouvés comme ceux d'avant vous — frappés par la détresse et la souffrance, secoués jusqu'à ce que le Messager dise : quand viendra le secours d'Allah ? Certes le secours d'Allah est proche !" },
  { id: 215, arabic: "يَسْأَلُونَكَ مَاذَا يُنفِقُونَ ۖ قُلْ مَا أَنفَقْتُم مِّنْ خَيْرٍ فَلِلْوَالِدَيْنِ وَالْأَقْرَبِينَ وَالْيَتَامَىٰ وَالْمَسَاكِينِ وَابْنِ السَّبِيلِ ۗ وَمَا تَفْعَلُوا مِنْ خَيْرٍ فَإِنَّ اللَّهَ بِهِ عَلِيمٌ", explication: "On t'interroge sur ce qu'ils doivent dépenser. Dis : tout bien que vous dépensez doit aller aux parents, proches, orphelins, pauvres et voyageurs. Allah connaît tout bien que vous faites." },
  { id: 216, arabic: "كُتِبَ عَلَيْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ ۖ وَعَسَىٰ أَن تَكْرَهُوا شَيْئًا وَهُوَ خَيْرٌ لَّكُمْ ۖ وَعَسَىٰ أَن تُحِبُّوا شَيْئًا وَهُوَ شَرٌّ لَّكُمْ ۗ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ", explication: "Le combat vous est prescrit, bien qu'il vous soit pénible. Il se peut que vous aimiez détester quelque chose qui est bon pour vous, et que vous aimiez quelque chose qui est mauvais. Allah sait et vous ne savez pas." },
  { id: 217, arabic: "يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ ۖ قُلْ قِتَالٌ فِيهِ كَبِيرٌ ۖ وَصَدٌّ عَن سَبِيلِ اللَّهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرَامِ وَإِخْرَاجُ أَهْلِهِ مِنْهُ أَكْبَرُ عِندَ اللَّهِ ۚ وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ ۗ وَلَا يَزَالُونَ يُقَاتِلُونَكُمْ حَتَّىٰ يَرُدُّوكُمْ عَن دِينِكُمْ إِنِ اسْتَطَاعُوا ۚ وَمَن يَرْتَدِدْ مِنكُمْ عَن دِينِهِ فَيَمُتْ وَهُوَ كَافِرٌ فَأُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَةِ ۖ وَأُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ", explication: "On t'interroge sur le combat durant le mois sacré. Dis : c'est grave, mais détourner du chemin d'Allah et expulser ses habitants de la Mosquée Sacrée est encore plus grave auprès d'Allah. La fitna est plus grave que le meurtre." },
  { id: 218, arabic: "إِنَّ الَّذِينَ آمَنُوا وَالَّذِينَ هَاجَرُوا وَجَاهَدُوا فِي سَبِيلِ اللَّهِ أُولَٰئِكَ يَرْجُونَ رَحْمَتَ اللَّهِ ۚ وَاللَّهُ غَفُورٌ رَّحِيمٌ", explication: "Ceux qui ont cru, émigré et combattu dans le chemin d'Allah espèrent la miséricorde d'Allah. Allah est Pardonneur, Miséricordieux." },
  { id: 219, arabic: "يَسْأَلُونَكَ عَنِ الْخَمْرِ وَالْمَيْسِرِ ۖ قُلْ فِيهِمَا إِثْمٌ كَبِيرٌ وَمَنَافِعُ لِلنَّاسِ وَإِثْمُهُمَا أَكْبَرُ مِن نَّفْعِهِمَا ۗ وَيَسْأَلُونَكَ مَاذَا يُنفِقُونَ قُلِ الْعَفْوَ ۗ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ", explication: "On t'interroge sur le vin et les jeux de hasard. Dis : ils contiennent un grand péché et des avantages pour les gens, mais leur péché est plus grand que leur avantage." },
  { id: 220, arabic: "فِي الدُّنْيَا وَالْآخِرَةِ ۗ وَيَسْأَلُونَكَ عَنِ الْيَتَامَىٰ ۖ قُلْ إِصْلَاحٌ لَّهُمْ خَيْرٌ ۖ وَإِن تُخَالِطُوهُمْ فَإِخْوَانُكُمْ ۚ وَاللَّهُ يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ ۚ وَلَوْ شَاءَ اللَّهُ لَأَعْنَتَكُمْ ۚ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ", explication: "En ce monde et dans l'au-delà. On t'interroge sur les orphelins. Dis : leur amélioration est meilleure. Si vous vous mêlez à eux, ils sont vos frères. Allah distingue le corrupteur du réformateur." },
  { id: 221, arabic: "وَلَا تَنكِحُوا الْمُشْرِكَاتِ حَتَّىٰ يُؤْمِنَّ ۚ وَلَأَمَةٌ مُّؤْمِنَةٌ خَيْرٌ مِّن مُّشْرِكَةٍ وَلَوْ أَعْجَبَتْكُمْ ۗ وَلَا تُنكِحُوا الْمُشْرِكِينَ حَتَّىٰ يُؤْمِنُوا ۚ وَلَعَبْدٌ مُّؤْمِنٌ خَيْرٌ مِّن مُّشْرِكٍ وَلَوْ أَعْجَبَكُمْ ۗ أُولَٰئِكَ يَدْعُونَ إِلَى النَّارِ ۖ وَاللَّهُ يَدْعُو إِلَى الْجَنَّةِ وَالْمَغْفِرَةِ بِإِذْنِهِ ۖ وَيُبَيِّنُ آيَاتِهِ لِلنَّاسِ لَعَلَّهُمْ يَتَذَكَّرُونَ", explication: "N'épousez pas les polythéistes tant qu'elles ne croient pas. Une esclave croyante vaut mieux qu'une polythéiste, même si elle vous plaît. Allah invite au Paradis et au pardon, les autres invitent au Feu." },
  { id: 222, arabic: "وَيَسْأَلُونَكَ عَنِ الْمَحِيضِ ۖ قُلْ هُوَ أَذًى فَاعْتَزِلُوا النِّسَاءَ فِي الْمَحِيضِ ۖ وَلَا تَقْرَبُوهُنَّ حَتَّىٰ يَطْهُرْنَ ۖ فَإِذَا تَطَهَّرْنَ فَأْتُوهُنَّ مِنْ حَيْثُ أَمَرَكُمُ اللَّهُ ۚ إِنَّ اللَّهَ يُحِبُّ التَّوَّابِينَ وَيُحِبُّ الْمُتَطَهِّرِينَ", explication: "On t'interroge sur les menstrues. Dis : c'est une gêne. Éloignez-vous des femmes pendant leurs menstrues et ne les approchez que quand elles sont purifiées. Allah aime ceux qui se repentent et ceux qui se purifient." },
  { id: 223, arabic: "نِسَاؤُكُمْ حَرْثٌ لَّكُمْ فَأْتُوا حَرْثَكُمْ أَنَّىٰ شِئْتُمْ ۖ وَقَدِّمُوا لِأَنفُسِكُمْ ۚ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّكُم مُّلَاقُوهُ ۗ وَبَشِّرِ الْمُؤْمِنِينَ", explication: "Vos femmes sont votre champ — approchez votre champ comme vous le souhaitez, et envoyez devant vous pour vous-mêmes. Craignez Allah et sachez que vous Le rencontrerez." },
  { id: 224, arabic: "وَلَا تَجْعَلُوا اللَّهَ عُرْضَةً لِّأَيْمَانِكُمْ أَن تَبَرُّوا وَتَتَّقُوا وَتُصْلِحُوا بَيْنَ النَّاسِ ۗ وَاللَّهُ سَمِيعٌ عَلِيمٌ", explication: "Ne faites pas d'Allah un prétexte pour vos serments pour éviter de faire le bien, d'être pieux et de réconcilier les gens. Allah est Audient, Omniscient." },
  { id: 225, arabic: "لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتْ قُلُوبُكُمْ ۗ وَاللَّهُ غَفُورٌ حَلِيمٌ", explication: "Allah ne vous prendra pas en compte pour les serments inconsidérés, mais vous en prendra compte pour ce que vos cœurs ont acquis. Allah est Pardonneur, Longanime." },
  { id: 226, arabic: "لِّلَّذِينَ يُؤْلُونَ مِن نِّسَائِهِمْ تَرَبُّصُ أَرْبَعَةِ أَشْهُرٍ ۖ فَإِن فَاءُوا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ", explication: "Ceux qui font le vœu de s'abstenir de leurs femmes ont un délai de quatre mois. S'ils reviennent, Allah est Pardonneur, Miséricordieux." },
  { id: 227, arabic: "وَإِنْ عَزَمُوا الطَّلَاقَ فَإِنَّ اللَّهَ سَمِيعٌ عَلِيمٌ", explication: "S'ils décident le divorce, Allah est Audient, Omniscient." },
  { id: 228, arabic: "وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ ۚ وَلَا يَحِلُّ لَهُنَّ أَن يَكْتُمْنَ مَا خَلَقَ اللَّهُ فِي أَرْحَامِهِنَّ إِن كُنَّ يُؤْمِنَّ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۚ وَبُعُولَتُهُنَّ أَحَقُّ بِرَدِّهِنَّ فِي ذَٰلِكَ إِن أَرَادُوا إِصْلَاحًا ۚ وَلَهُنَّ مِثْلُ الَّذِي عَلَيْهِنَّ بِالْمَعْرُوفِ ۚ وَلِلرِّجَالِ عَلَيْهِنَّ دَرَجَةٌ ۗ وَاللَّهُ عَزِيزٌ حَكِيمٌ", explication: "Les femmes divorcées attendent trois périodes. Leurs maris ont plus droit de les reprendre pendant ce délai s'ils veulent se réconcilier. Les femmes ont des droits équivalents à leurs obligations. Les hommes ont un degré de plus sur elles." },
  { id: 229, arabic: "الطَّلَاقُ مَرَّتَانِ ۖ فَإِمْسَاكٌ بِمَعْرُوفٍ أَوْ تَسْرِيحٌ بِإِحْسَانٍ ۗ وَلَا يَحِلُّ لَكُمْ أَن تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا إِلَّا أَن يَخَافَا أَلَّا يُقِيمَا حُدُودَ اللَّهِ ۖ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ ۗ تِلْكَ حُدُودُ اللَّهِ فَلَا تَعْتَدُوهَا ۚ وَمَن يَتَعَدَّ حُدُودَ اللَّهِ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ", explication: "Le divorce (révocable) est deux fois. Ensuite soit garder avec bienveillance, soit relâcher avec bonté. Il ne vous est pas permis de reprendre ce que vous leur avez donné, sauf si les deux craignent de ne pas respecter les limites d'Allah (khul')." },
  { id: 230, arabic: "فَإِن طَلَّقَهَا فَلَا تَحِلُّ لَهُ مِن بَعْدُ حَتَّىٰ تَنكِحَ زَوْجًا غَيْرَهُ ۗ فَإِن طَلَّقَهَا فَلَا جُنَاحَ عَلَيْهِمَا أَن يَتَرَاجَعَا إِن ظَنَّا أَن يُقِيمَا حُدُودَ اللَّهِ ۗ وَتِلْكَ حُدُودُ اللَّهِ يُبَيِّنُهَا لِقَوْمٍ يَعْلَمُونَ", explication: "S'il la divorce (une troisième fois), elle ne lui sera plus licite à moins qu'elle n'épouse un autre mari. Si ce dernier la divorce, pas de péché pour eux à se réunir s'ils pensent respecter les limites d'Allah." },
  { id: 231, arabic: "وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ سَرِّحُوهُنَّ بِمَعْرُوفٍ ۚ وَلَا تُمْسِكُوهُنَّ ضِرَارًا لِّتَعْتَدُوا ۚ وَمَن يَفْعَلْ ذَٰلِكَ فَقَدْ ظَلَمَ نَفْسَهُ ۚ وَلَا تَتَّخِذُوا آيَاتِ اللَّهِ هُزُوًا ۚ وَاذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ وَمَا أَنزَلَ عَلَيْكُم مِّنَ الْكِتَابِ وَالْحِكْمَةِ يَعِظُكُم بِهِ ۚ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ", explication: "Quand vous divorciez d'avec des femmes et qu'elles arrivent au terme de leur attente, retenez-les convenablement ou libérez-les convenablement. Ne les retenez pas pour leur nuire. Quiconque fait cela s'injuste lui-même. Ne prenez pas les versets d'Allah en dérision." },
  { id: 232, arabic: "وَإِذَا طَلَّقْتُمُ النِّسَاءَ فَبَلَغْنَ أَجَلَهُنَّ فَلَا تَعْضُلُوهُنَّ أَن يَنكِحْنَ أَزْوَاجَهُنَّ إِذَا تَرَاضَوْا بَيْنَهُم بِالْمَعْرُوفِ ۗ ذَٰلِكَ يُوعَظُ بِهِ مَن كَانَ مِنكُمْ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۗ ذَٰلِكُمْ أَزْكَىٰ لَكُمْ وَأَطْهَرُ ۗ وَاللَّهُ يَعْلَمُ وَأَنتُمْ لَا تَعْلَمُونَ", explication: "Quand vous divorciez des femmes et qu'elles arrivent au terme de leur attente, ne les empêchez pas d'épouser leurs (futurs) époux s'ils se sont mis d'accord convenablement." },
  { id: 233, arabic: "وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ ۖ لِمَنْ أَرَادَ أَن يُتِمَّ الرَّضَاعَةَ ۚ وَعَلَى الْمَوْلُودِ لَهُ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ ۚ لَا تُكَلَّفُ نَفْسٌ إِلَّا وُسْعَهَا ۚ لَا تُضَارَّ وَالِدَةٌ بِوَلَدِهَا وَلَا مَوْلُودٌ لَّهُ بِوَلَدِهِ ۚ وَعَلَى الْوَارِثِ مِثْلُ ذَٰلِكَ ۗ فَإِنْ أَرَادَا فِصَالًا عَن تَرَاضٍ مِّنْهُمَا وَتَشَاوُرٍ فَلَا جُنَاحَ عَلَيْهِمَا ۗ وَإِنْ أَرَدتُّمْ أَن تَسْتَرْضِعُوا أَوْلَادَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُم مَّا آتَيْتُم بِالْمَعْرُوفِ ۗ وَاتَّقُوا اللَّهَ وَاعْلَمُوا أَنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ", explication: "Les mères allaitent leurs enfants deux ans complets pour ceux qui veulent compléter l'allaitement. L'obligation alimentaire et vestimentaire incombe au père de façon convenable. Nul n'est chargé au-delà de ses moyens." },
  { id: 234, arabic: "وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا ۖ فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ بِالْمَعْرُوفِ ۗ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ", explication: "Ceux d'entre vous qui meurent et laissent des épouses — celles-ci doivent observer une période d'attente de quatre mois et dix jours. Quand elles auront atteint leur terme, vous n'aurez pas de péché pour ce qu'elles feront d'elles-mêmes convenablement. Allah est Informé de ce que vous faites." },
  { id: 235, arabic: "وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِ مِنْ خِطْبَةِ النِّسَاءِ أَوْ أَكْنَنتُمْ فِي أَنفُسِكُمْ ۚ عَلِمَ اللَّهُ أَنَّكُمْ لَن تَذْكُرُوهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّا أَن تَقُولُوا قَوْلًا مَّعْرُوفًا ۚ وَلَا تَعْزِمُوا عُقْدَةَ النِّكَاحِ حَتَّىٰ يَنقَضِيَ الْكِتَابُ أَجَلُهُ ۚ وَاعْلَمُوا أَنَّ اللَّهَ يَعْلَمُ مَا فِي أَنفُسِكُمْ فَاحْذَرُوهُ ۚ وَاعْلَمُوا أَنَّ اللَّهَ غَفُورٌ حَلِيمٌ", explication: "Il n'y a pas de péché à faire allusion à une demande en mariage ou à la garder en vous. Allah sait que vous ne les oublierez pas, mais ne leur faites pas de promesses secrètes sauf paroles convenables. Ne concluez pas le mariage avant l'expiration du délai légal." },
  { id: 236, arabic: "لَّا جُنَاحَ عَلَيْكُمْ إِن طَلَّقْتُمُ النِّسَاءَ مَا لَمْ تَمَسُّوهُنَّ أَوْ تَفْرِضُوا لَهُنَّ فَرِيضَةً ۚ وَمَتِّعُوهُنَّ عَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ مَتَاعًا بِالْمَعْرُوفِ ۖ حَقًّا عَلَى الْمُحْسِنِينَ", explication: "Pas de péché si vous divorcez des femmes avant de les avoir touchées ou de leur avoir assigné une dot. Donnez-leurs un avantage selon vos moyens, convenablement — c'est un devoir envers les bienfaisants." },
  { id: 237, arabic: "وَإِن طَلَّقْتُمُوهُنَّ مِن قَبْلِ أَن تَمَسُّوهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِيضَةً فَنِصْفُ مَا فَرَضْتُمْ إِلَّا أَن يَعْفُونَ أَوْ يَعْفُوَ الَّذِي بِيَدِهِ عُقْدَةُ النِّكَاحِ ۚ وَأَن تَعْفُوا أَقْرَبُ لِلتَّقْوَىٰ ۚ وَلَا تَنسَوُا الْفَضْلَ بَيْنَكُمْ ۚ إِنَّ اللَّهَ بِمَا تَعْمَلُونَ بَصِيرٌ", explication: "Si vous les divorcez avant de les avoir touchées et que vous leur avez assigné une dot, elles ont droit à la moitié, à moins qu'elles n'y renoncent ou que le mari n'y renonce. Pardonner est plus proche de la piété." },
  { id: 238, arabic: "حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَىٰ وَقُومُوا لِلَّهِ قَانِتِينَ", explication: "Observez scrupuleusement les prières, et la prière du milieu (Asr), et tenez-vous devant Allah dans l'humilité." },
  { id: 239, arabic: "فَإِنْ خِفْتُمْ فَرِجَالًا أَوْ رُكْبَانًا ۖ فَإِذَا أَمِنتُمْ فَاذْكُرُوا اللَّهَ كَمَا عَلَّمَكُم مَّا لَمْ تَكُونُوا تَعْلَمُونَ", explication: "Si vous craignez (l'ennemi), faites-la à pied ou à cheval. Puis quand vous serez en sécurité, évoquez Allah comme Il vous a appris ce que vous ne saviez pas." },
  { id: 240, arabic: "وَالَّذِينَ يُتَوَفَّوْنَ مِنكُمْ وَيَذَرُونَ أَزْوَاجًا وَصِيَّةً لِّأَزْوَاجِهِم مَّتَاعًا إِلَى الْحَوْلِ غَيْرَ إِخْرَاجٍ ۖ فَإِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَيْكُمْ فِي مَا فَعَلْنَ فِي أَنفُسِهِنَّ مِن مَّعْرُوفٍ ۗ وَاللَّهُ عَزِيزٌ حَكِيمٌ", explication: "Ceux qui meurent et laissent des épouses doivent léguer à celles-ci un hébergement d'un an sans les expulser. Si elles partent d'elles-mêmes, pas de péché pour ce qu'elles font convenablement." },
  { id: 241, arabic: "وَلِلْمُطَلَّقَاتِ مَتَاعٌ بِالْمَعْرُوفِ ۖ حَقًّا عَلَى الْمُتَّقِينَ", explication: "Les femmes divorcées ont droit à un avantage convenable — c'est un devoir pour les pieux." },
  { id: 242, arabic: "كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمْ آيَاتِهِ لَعَلَّكُمْ تَعْقِلُونَ", explication: "Ainsi Allah vous explique Ses versets — peut-être comprendrez-vous." },
  { id: 243, arabic: "أَلَمْ تَرَ إِلَى الَّذِينَ خَرَجُوا مِن دِيَارِهِمْ وَهُمْ أُلُوفٌ حَذَرَ الْمَوْتِ فَقَالَ لَهُمُ اللَّهُ مُوتُوا ثُمَّ أَحْيَاهُمْ ۚ إِنَّ اللَّهَ لَذُو فَضْلٍ عَلَى النَّاسِ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يَشْكُرُونَ", explication: "N'as-tu pas vu ceux qui sont sortis de leurs demeures par milliers, par crainte de la mort ? Allah leur dit : mourez ! Puis Il les a fait revivre. Allah est Digne de faveur pour les gens, mais la plupart ne sont pas reconnaissants." },
  { id: 244, arabic: "وَقَاتِلُوا فِي سَبِيلِ اللَّهِ وَاعْلَمُوا أَنَّ اللَّهَ سَمِيعٌ عَلِيمٌ", explication: "Combattez dans le chemin d'Allah et sachez qu'Il est Audient, Omniscient." },
  { id: 245, arabic: "مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ لَهُ أَضْعَافًا كَثِيرَةً ۚ وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ", explication: "Qui est celui qui prête à Allah un bon prêt pour qu'Il le multiplie pour lui plusieurs fois ? Allah resserre et étend, et c'est vers Lui que vous serez ramenés." },
  { id: 246, arabic: "أَلَمْ تَرَ إِلَى الْمَلَإِ مِن بَنِي إِسْرَائِيلَ مِن بَعْدِ مُوسَىٰ إِذْ قَالُوا لِنَبِيٍّ لَّهُمُ ابْعَثْ لَنَا مَلِكًا نُّقَاتِلْ فِي سَبِيلِ اللَّهِ ۖ قَالَ هَلْ عَسَيْتُمْ إِن كُتِبَ عَلَيْكُمُ الْقِتَالُ أَلَّا تُقَاتِلُوا ۖ قَالُوا وَمَا لَنَا أَلَّا نُقَاتِلَ فِي سَبِيلِ اللَّهِ وَقَدْ أَخْرَجْنَا مِن دِيَارِنَا وَأَبْنَائِنَا ۖ فَلَمَّا كُتِبَ عَلَيْهِمُ الْقِتَالُ تَوَلَّوْا إِلَّا قَلِيلًا مِّنْهُمْ ۗ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ", explication: "N'as-tu pas vu les notables des Banû Isrâ'îl après Moïse, quand ils demandèrent un roi pour combattre dans le chemin d'Allah ? Puis quand le combat leur fut prescrit, ils se détournèrent, sauf quelques-uns." },
  { id: 247, arabic: "وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ اللَّهَ قَدْ بَعَثَ لَكُمْ طَالُوتَ مَلِكًا ۚ قَالُوا أَنَّىٰ يَكُونُ لَهُ الْمُلْكُ عَلَيْنَا وَنَحْنُ أَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ يُؤْتَ سَعَةً مِّنَ الْمَالِ ۖ قَالَ إِنَّ اللَّهَ اصْطَفَاهُ عَلَيْكُمْ وَزَادَهُ بَسْطَةً فِي الْعِلْمِ وَالْجِسْمِ ۖ وَاللَّهُ يُؤْتِي مُلْكَهُ مَن يَشَاءُ ۚ وَاللَّهُ وَاسِعٌ عَلِيمٌ", explication: "Leur prophète leur dit : Allah vous a désigné Saül (Tâlût) comme roi. Ils dirent : comment pourrait-il régner sur nous, nous qui sommes plus dignes ? Il dit : Allah l'a choisi et lui a donné une supériorité en science et en stature." },
  { id: 248, arabic: "وَقَالَ لَهُمْ نَبِيُّهُمْ إِنَّ آيَةَ مُلْكِهِ أَن يَأْتِيَكُمُ التَّابُوتُ فِيهِ سَكِينَةٌ مِّن رَّبِّكُمْ وَبَقِيَّةٌ مِّمَّا تَرَكَ آلُ مُوسَىٰ وَآلُ هَارُونَ تَحْمِلُهُ الْمَلَائِكَةُ ۚ إِنَّ فِي ذَٰلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ", explication: "Leur prophète dit : le signe de son autorité est que l'Arche viendra à vous, apportant la tranquillité de votre Seigneur et les reliques de ce qu'ont laissé la famille de Moïse et d'Aaron, portée par les anges." },
  { id: 249, arabic: "فَلَمَّا فَصَلَ طَالُوتُ بِالْجُنُودِ قَالَ إِنَّ اللَّهَ مُبْتَلِيكُم بِنَهَرٍ فَمَن شَرِبَ مِنْهُ فَلَيْسَ مِنِّي وَمَن لَّمْ يَطْعَمْهُ فَإِنَّهُ مِنِّي إِلَّا مَنِ اغْتَرَفَ غُرْفَةً بِيَدِهِ ۚ فَشَرِبُوا مِنْهُ إِلَّا قَلِيلًا مِّنْهُمْ ۖ فَلَمَّا جَاوَزَهُ هُوَ وَالَّذِينَ آمَنُوا مَعَهُ قَالُوا لَا طَاقَةَ لَنَا الْيَوْمَ بِجَالُوتَ وَجُنُودِهِ ۚ قَالَ الَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَاقُو اللَّهِ كَم مِّن فِئَةٍ قَلِيلَةٍ غَلَبَتْ فِئَةً كَثِيرَةً بِإِذْنِ اللَّهِ ۗ وَاللَّهُ مَعَ الصَّابِرِينَ", explication: "Quand Saül se mit en marche avec l'armée, il dit : Allah vous éprouve par une rivière. Quiconque en boit n'est plus des miens, sauf celui qui en prend une poignée. La plupart la burent. Ceux qui étaient certains de rencontrer Allah dirent : combien de petites troupes ont vaincu de grandes troupes par la permission d'Allah !" },
  { id: 250, arabic: "وَلَمَّا بَرَزُوا لِجَالُوتَ وَجُنُودِهِ قَالُوا رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ", explication: "Quand ils furent face à Goliath (Jâlût) et ses troupes, ils dirent : Seigneur, répands sur nous la patience, affermis nos pas et accorde-nous la victoire sur les gens qui ont mécru." },
  { id: 251, arabic: "فَهَزَمُوهُم بِإِذْنِ اللَّهِ وَقَتَلَ دَاوُودُ جَالُوتَ وَآتَاهُ اللَّهُ الْمُلْكَ وَالْحِكْمَةَ وَعَلَّمَهُ مِمَّا يَشَاءُ ۗ وَلَوْلَا دَفْعُ اللَّهِ النَّاسَ بَعْضَهُم بِبَعْضٍ لَّفَسَدَتِ الْأَرْضُ وَلَٰكِنَّ اللَّهَ ذُو فَضْلٍ عَلَى الْعَالَمِينَ", explication: "Ils les vainquirent par la permission d'Allah, et David (Dâwûd) tua Goliath. Allah lui donna la royauté, la sagesse et lui apprit ce qu'Il voulut. Si Allah ne repoussait pas les gens les uns par les autres, la terre serait corrompue." },
  { id: 252, arabic: "تِلْكَ آيَاتُ اللَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ ۚ وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ", explication: "Ce sont là les versets d'Allah que Nous te récitons avec la vérité. Tu es vraiment du nombre des messagers." },
  { id: 253, arabic: "تِلْكَ الرُّسُلُ فَضَّلْنَا بَعْضَهُمْ عَلَىٰ بَعْضٍ ۘ مِّنْهُم مَّن كَلَّمَ اللَّهُ ۖ وَرَفَعَ بَعْضَهُمْ دَرَجَاتٍ ۚ وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ ۗ وَلَوْ شَاءَ اللَّهُ مَا الْتَقَى الَّذِينَ مِن بَعْدِهِم مِّن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَاتُ وَلَٰكِنِ اخْتَلَفُوا فَمِنْهُم مَّنْ آمَنَ وَمِنْهُم مَّن كَفَرَ ۚ وَلَوْ شَاءَ اللَّهُ مَا الْتَقَوْا وَلَٰكِنَّ اللَّهَ يَفْعَلُ مَا يُرِيدُ", explication: "Nous avons préféré certains messagers à d'autres. Parmi eux, il y en a à qui Allah a parlé, et Il en a élevé d'autres en degrés. Nous avons donné à Jésus les preuves et l'avons aidé par l'Esprit Saint." },
  { id: 254, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا خُلَّةٌ وَلَا شَفَاعَةٌ ۗ وَالْكَافِرُونَ هُمُ الظَّالِمُونَ", explication: "Ô croyants ! Dépensez de ce que Nous vous avons accordé avant qu'il ne vienne un jour où il n'y aura ni commerce, ni amitié, ni intercession. Les mécréants sont les injustes." },
  { id: 255, arabic: "اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَن ذَا الَّذِي يَشْفَعُ عِندَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ", explication: "Allah ! Pas de divinité que Lui, le Vivant, Celui qui subsiste par Lui-même. Ni somnolence ni sommeil ne Le saisissent. À Lui appartient tout ce qui est dans les cieux et sur la terre. Qui intercèdera auprès de Lui sans Sa permission ? Il sait ce qui est devant eux et derrière eux, et ils n'embrassent rien de Sa science que ce qu'Il veut. Son Trône s'étend sur les cieux et la terre, et leur conservation ne Lui est pas pénible. Il est le Très Haut, le Grand." },
  { id: 256, arabic: "لَا إِكْرَاهَ فِي الدِّينِ ۖ قَد تَّبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ ۚ فَمَن يَكْفُرْ بِالطَّاغُوتِ وَيُؤْمِن بِاللَّهِ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَىٰ لَا انفِصَامَ لَهَا ۗ وَاللَّهُ سَمِيعٌ عَلِيمٌ", explication: "Nulle contrainte en religion ! Car le bon chemin s'est distingué de l'égarement. Quiconque mécroît au Tyran et croit en Allah saisit l'anse la plus solide qui ne se brise pas. Allah est Audient, Omniscient." },
  { id: 257, arabic: "اللَّهُ وَلِيُّ الَّذِينَ آمَنُوا يُخْرِجُهُم مِّنَ الظُّلُمَاتِ إِلَى النُّورِ ۖ وَالَّذِينَ كَفَرُوا أَوْلِيَاؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُم مِّنَ النُّورِ إِلَى الظُّلُمَاتِ ۗ أُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ", explication: "Allah est le Protecteur de ceux qui ont cru : Il les fait sortir des ténèbres vers la lumière. Ceux qui ont mécru ont pour protecteurs les tyrans qui les font sortir de la lumière vers les ténèbres. Ceux-là sont les gens du Feu, où ils demeureront." },
  { id: 258, arabic: "أَلَمْ تَرَ إِلَى الَّذِي حَاجَّ إِبْرَاهِيمَ فِي رَبِّهِ أَنْ آتَاهُ اللَّهُ الْمُلْكَ إِذْ قَالَ إِبْرَاهِيمُ رَبِّيَ الَّذِي يُحْيِي وَيُمِيتُ قَالَ أَنَا أُحْيِي وَأُمِيتُ ۖ قَالَ إِبْرَاهِيمُ فَإِنَّ اللَّهَ يَأْتِي بِالشَّمْسِ مِنَ الْمَشْرِقِ فَأْتِ بِهَا مِنَ الْمَغْرِبِ فَبُهِتَ الَّذِي كَفَرَ ۗ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ", explication: "N'as-tu pas vu celui qui disputa Ibrahim au sujet de son Seigneur, alors qu'Allah lui avait donné la royauté ? Ibrahim dit : c'est mon Seigneur qui fait vivre et fait mourir. Il dit : moi aussi je fais vivre et fais mourir. Ibrahim dit : Allah fait venir le soleil de l'orient, amène-le de l'occident ! Celui qui avait mécru resta confondu." },
  { id: 259, arabic: "أَوْ كَالَّذِي مَرَّ عَلَىٰ قَرْيَةٍ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحْيِي هَٰذِهِ اللَّهُ بَعْدَ مَوْتِهَا ۖ فَأَمَاتَهُ اللَّهُ مِائَةَ عَامٍ ثُمَّ بَعَثَهُ ۚ قَالَ كَمْ لَبِثْتَ ۖ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ ۖ قَالَ بَل لَّبِثْتَ مِائَةَ عَامٍ فَانظُرْ إِلَىٰ طَعَامِكَ وَشَرَابِكَ يَمَسُّهُ الشَّمْسُ ۖ وَانظُرْ إِلَىٰ حِمَارِكَ وَلِنَجْعَلَكَ آيَةً لِّلنَّاسِ ۖ وَانظُرْ إِلَى الْعِظَامِ كَيْفَ نُنشِزُهَا ثُمَّ نَكْسُوهَا لَحْمًا ۚ فَلَمَّا تَبَيَّنَ لَهُ قَالَ أَعْلَمُ أَنَّ اللَّهَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", explication: "Ou comme celui qui passa par une cité renversée sur ses toits et dit : comment Allah va-t-Il la vivifier après sa mort ? Allah le fit mourir cent ans, puis le ressuscita. Regarde ton repas et ta boisson, ils n'ont pas changé, et ton âne. Nous ferons de toi un signe pour les gens. Regarde les os comment Nous les rassemblons et les revêtons de chair. Il dit : je sais qu'Allah est Puissant sur toute chose." },
  { id: 260, arabic: "وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَىٰ ۖ قَالَ أَوَلَمْ تُؤْمِن ۖ قَالَ بَلَىٰ وَلَٰكِن لِّيَطْمَئِنَّ قَلْبِي ۖ قَالَ فَخُذْ أَرْبَعَةً مِّنَ الطَّيْرِ فَصُرْهُنَّ إِلَيْكَ ثُمَّ اجْعَلْ عَلَىٰ كُلِّ جَبَلٍ مِّنْهُنَّ جُزْءًا ثُمَّ ادْعُهُنَّ يَأْتِينَكَ سَعْيًا ۚ وَاعْلَمْ أَنَّ اللَّهَ عَزِيزٌ حَكِيمٌ", explication: "Quand Ibrahim dit : Seigneur, montre-moi comment Tu fais revivre les morts. Il dit : n'as-tu pas cru ? Il dit : si, mais pour que mon cœur soit tranquille. Il dit : prends quatre oiseaux, apprivoise-les, puis pose sur chaque montagne une partie d'eux, puis appelle-les, ils viendront vers toi en hâte. Sache qu'Allah est Puissant, Sage." },
  { id: 261, arabic: "مَّثَلُ الَّذِينَ يُنفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ كَمَثَلِ حَبَّةٍ أَنبَتَتْ سَبْعَ سَنَابِلَ فِي كُلِّ سُنبُلَةٍ مِّائَةُ حَبَّةٍ ۗ وَاللَّهُ يُضَاعِفُ لِمَن يَشَاءُ ۗ وَاللَّهُ وَاسِعٌ عَلِيمٌ", explication: "L'exemple de ceux qui dépensent leurs biens dans le chemin d'Allah est comme une semence qui produit sept épis, chaque épi contenant cent grains. Allah multiplie pour qui Il veut. Il est Vaste, Omniscient." },
  { id: 262, arabic: "الَّذِينَ يُنفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ ثُمَّ لَا يُتْبِعُونَ مَا أَنفَقُوا مَنًّا وَلَا أَذًى ۙ لَّهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", explication: "Ceux qui dépensent leurs biens dans le chemin d'Allah et ne suivent pas ce qu'ils ont dépensé de reproche ni de nuisance, auront leur récompense auprès de leur Seigneur. Pas de crainte pour eux ni de tristesse." },
  { id: 263, arabic: "قَوْلٌ مَّعْرُوفٌ وَمَغْفِرَةٌ خَيْرٌ مِّن صَدَقَةٍ يَتْبَعُهَا أَذًى ۗ وَاللَّهُ غَنِيٌّ حَلِيمٌ", explication: "Une parole de bienveillance et un pardon valent mieux qu'une aumône suivie de nuisance. Allah est Indigent de personne, Longanime." },
  { id: 264, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُبْطِلُوا صَدَقَاتِكُم بِالْمَنِّ وَالْأَذَىٰ كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ۖ فَمَثَلُهُ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُ وَابِلٌ فَتَرَكَهُ صَلْدًا ۖ لَّا يَقْدِرُونَ عَلَىٰ شَيْءٍ مِّمَّا كَسَبُوا ۗ وَاللَّهُ لَا يَهْدِي الْقَوْمَ الْكَافِرِينَ", explication: "Ô croyants ! Ne rendez pas vaines vos aumônes par le reproche et la nuisance, comme celui qui dépense pour être vu des gens sans croire en Allah et au Jour dernier. Son exemple est comme une pierre couverte de poussière qu'une averse laisse nue." },
  { id: 265, arabic: "وَمَثَلُ الَّذِينَ يُنفِقُونَ أَمْوَالَهُمُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ وَتَثْبِيتًا مِّنْ أَنفُسِهِمْ كَمَثَلِ جَنَّةٍ بِرَبْوَةٍ أَصَابَهَا وَابِلٌ فَآتَتْ أُكُلَهَا ضِعْفَيْنِ فَإِن لَّمْ يُصِبْهَا وَابِلٌ فَطَلٌّ ۗ وَاللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌ", explication: "L'exemple de ceux qui dépensent leurs biens pour la satisfaction d'Allah et pour affermir leurs âmes est comme un jardin sur une hauteur : une averse l'abonde doublement, et s'il n'y a pas d'averse, la rosée suffit. Allah voit ce que vous faites." },
  { id: 266, arabic: "أَيَوَدُّ أَحَدُكُمْ أَن تَكُونَ لَهُ جَنَّةٌ مِّن نَّخِيلٍ وَأَعْنَابٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ لَهُ فِيهَا مِن كُلِّ الثَّمَرَاتِ وَأَصَابَهُ الْكِبَرُ وَلَهُ ذُرِّيَّةٌ ضُعَفَاءُ فَأَصَابَهَا إِعْصَارٌ فِيهِ نَارٌ فَاحْتَرَقَتْ ۗ كَذَٰلِكَ يُبَيِّنُ اللَّهُ لَكُمُ الْآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ", explication: "L'un de vous aimerait-il avoir un jardin de palmiers et de vignes avec des rivières, et qu'il soit frappé par la vieillesse avec une descendance faible, puis qu'un ouragan avec feu le consume ? Ainsi Allah vous explique Ses versets afin que vous réfléchissiez." },
  { id: 267, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا أَنفِقُوا مِن طَيِّبَاتِ مَا كَسَبْتُمْ وَمِمَّا أَخْرَجْنَا لَكُم مِّنَ الْأَرْضِ ۖ وَلَا تَيَمَّمُوا الْخَبِيثَ مِنْهُ تُنفِقُونَ وَلَسْتُم بِآخِذِيهِ إِلَّا أَن تُغْمِضُوا فِيهِ ۚ وَاعْلَمُوا أَنَّ اللَّهَ غَنِيٌّ حَمِيدٌ", explication: "Ô croyants ! Dépensez du meilleur de ce que vous avez gagné et de ce que Nous avons fait sortir de la terre pour vous. Ne visez pas le mauvais pour en faire l'aumône, ce que vous n'accepteriez vous-mêmes qu'en fermant les yeux." },
  { id: 268, arabic: "الشَّيْطَانُ يَعِدُكُمُ الْفَقْرَ وَيَأْمُرُكُم بِالْفَحْشَاءِ ۖ وَاللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلًا ۗ وَاللَّهُ وَاسِعٌ عَلِيمٌ", explication: "Le Diable vous promet la pauvreté et vous ordonne l'indécence. Allah vous promet Son pardon et Sa grâce. Allah est Vaste, Omniscient." },
  { id: 269, arabic: "يُؤْتِي الْحِكْمَةَ مَن يَشَاءُ ۚ وَمَن يُؤْتَ الْحِكْمَةَ فَقَدْ أُوتِيَ خَيْرًا كَثِيرًا ۗ وَمَا يَذَّكَّرُ إِلَّا أُولُو الْأَلْبَابِ", explication: "Il donne la sagesse à qui Il veut. Quiconque reçoit la sagesse a reçu un immense bien. Mais seuls les doués d'intelligence s'en souviennent." },
  { id: 270, arabic: "وَمَا أَنفَقْتُم مِّن نَّفَقَةٍ أَوْ نَذَرْتُم مِّن نَّذْرٍ فَإِنَّ اللَّهَ يَعْلَمُهُ ۗ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ", explication: "Toute dépense que vous faites ou tout vœu que vous prononcez, Allah le sait. Et les injustes n'ont pas de secoureurs." },
  { id: 271, arabic: "إِن تُبْدُوا الصَّدَقَاتِ فَنِعِمَّا هِيَ ۖ وَإِن تُخْفُوهَا وَتُؤْتُوهَا الْفُقَرَاءَ فَهُوَ خَيْرٌ لَّكُمْ ۚ وَيُكَفِّرُ عَنكُم مِّن سَيِّئَاتِكُمْ ۗ وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ", explication: "Si vous rendez les aumônes publiques, c'est bien. Mais si vous les cachez et les donnez aux pauvres, c'est encore mieux pour vous. Il vous effacera vos péchés, et Allah est Informé de ce que vous faites." },
  { id: 272, arabic: "لَّيْسَ عَلَيْكَ هُدَاهُمْ وَلَٰكِنَّ اللَّهَ يَهْدِي مَن يَشَاءُ ۗ وَمَا تُنفِقُوا مِنْ خَيْرٍ فَلِأَنفُسِكُمْ ۗ وَمَا تُنفِقُونَ إِلَّا ابْتِغَاءَ وَجْهِ اللَّهِ ۗ وَمَا تُنفِقُوا مِنْ خَيْرٍ يُوَفَّ إِلَيْكُمْ وَأَنتُمْ لَا تُظْلَمُونَ", explication: "Tu n'es pas responsable de leur guidance, mais Allah guide qui Il veut. Tout bien que vous dépensez est pour vous-mêmes. Vous ne dépensez que pour la Face d'Allah, et vous serez remboursés sans être lésés." },
  { id: 273, arabic: "لِلْفُقَرَاءِ الَّذِينَ أُحْصِرُوا فِي سَبِيلِ اللَّهِ لَا يَسْتَطِيعُونَ ضَرْبًا فِي الْأَرْضِ يَحْسَبُهُمُ الْجَاهِلُ أَغْنِيَاءَ مِنَ التَّعَفُّفِ ۚ تَعْرِفُهُم بِسِيمَاهُمْ لَا يَسْأَلُونَ النَّاسَ إِلَّاحًا ۚ وَمَا تُنفِقُوا مِنْ خَيْرٍ فَإِنَّ اللَّهَ بِهِ عَلِيمٌ", explication: "C'est pour les pauvres retenus dans le chemin d'Allah, incapables de voyager sur terre. L'ignorant les croirait riches à cause de leur pudeur. Tu les reconnais à leurs traits : ils ne demandent pas aux gens importunément." },
  { id: 274, arabic: "الَّذِينَ يُنفِقُونَ أَمْوَالَهُم بِاللَّيْلِ وَالنَّهَارِ سِرًّا وَعَلَانِيَةً فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", explication: "Ceux qui dépensent leurs biens de nuit et de jour, secrètement et publiquement, auront leur récompense auprès de leur Seigneur. Pas de crainte pour eux ni de tristesse." },
  { id: 275, arabic: "الَّذِينَ يَأْكُلُونَ الرِّبَا لَا يَقُومُونَ إِلَّا كَمَا يَقُومُ الَّذِي يَتَخَبَّطُهُ الشَّيْطَانُ مِنَ الْمَسِّ ۚ ذَٰلِكَ بِأَنَّهُمْ قَالُوا إِنَّمَا الْبَيْعُ مِثْلُ الرِّبَا ۗ وَأَحَلَّ اللَّهُ الْبَيْعَ وَحَرَّمَ الرِّبَا ۚ فَمَن جَاءَهُ مَوْعِظَةٌ مِّن رَّبِّهِ فَانتَهَىٰ فَلَهُ مَا سَلَفَ وَأَمْرُهُ إِلَى اللَّهِ ۖ وَمَنْ عَادَ فَأُولَٰئِكَ أَصْحَابُ النَّارِ ۖ هُمْ فِيهَا خَالِدُونَ", explication: "Ceux qui consomment l'usure ne se lèveront que comme se lève celui que le Diable terrasse par le toucher. C'est parce qu'ils ont dit : le commerce est comme l'usure. Allah a rendu licite le commerce et interdit l'usure." },
  { id: 276, arabic: "يَمْحَقُ اللَّهُ الرِّبَا وَيُرْبِي الصَّدَقَاتِ ۗ وَاللَّهُ لَا يُحِبُّ كُلَّ كَفَّارٍ أَثِيمٍ", explication: "Allah anéantit l'usure et fait fructifier les aumônes. Allah n'aime pas tout ingrat pécheur." },
  { id: 277, arabic: "إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَأَقَامُوا الصَّلَاةَ وَآتَوُا الزَّكَاةَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", explication: "Ceux qui croient, font de bonnes œuvres, accomplissent la prière et acquittent la Zakât auront leur récompense auprès de leur Seigneur. Pas de crainte pour eux ni de tristesse." },
  { id: 278, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِن كُنتُم مُّؤْمِنِينَ", explication: "Ô croyants ! Craignez Allah et renoncez au reliquat de l'usure, si vous êtes croyants." },
  { id: 279, arabic: "فَإِن لَّمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِّنَ اللَّهِ وَرَسُولِهِ ۖ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ", explication: "Si vous ne le faites pas, sachez que vous êtes en guerre contre Allah et Son messager. Mais si vous vous repentez, vous aurez vos capitaux. Ne commettez pas d'injustice et vous ne serez pas lésés." },
  { id: 280, arabic: "وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ ۚ وَأَن تَصَدَّقُوا خَيْرٌ لَّكُمْ ۖ إِن كُنتُمْ تَعْلَمُونَ", explication: "Si le débiteur est en difficulté, accordez-lui un délai jusqu'à ce qu'il soit à l'aise. Et si vous en faites aumône, c'est encore mieux pour vous, si vous saviez." },
  { id: 281, arabic: "وَاتَّقُوا يَوْمًا تُرْجَعُونَ فِيهِ إِلَى اللَّهِ ۖ ثُمَّ تُوَفَّىٰ كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ", explication: "Craignez le Jour où vous serez ramenés à Allah, puis chaque âme sera pleinement rétribuée de ce qu'elle a acquis, et ils ne seront pas lésés." },
  { id: 282, arabic: "يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا تَدَايَنتُم بِدَيْنٍ إِلَىٰ أَجَلٍ مُّسَمًّى فَاكْتُبُوهُ ۚ وَلْيَكْتُب بَّيْنَكُمْ كَاتِبٌ بِالْعَدْلِ ۚ وَلَا يَأْبَ كَاتِبٌ أَن يَكْتُبَ كَمَا عَلَّمَهُ اللَّهُ ۚ فَلْيَكْتُبْ وَلْيُمْلِلِ الَّذِي عَلَيْهِ الْحَقُّ وَلْيَتَّقِ اللَّهَ رَبَّهُ وَلَا يَبْخَسْ مِنْهُ شَيْئًا ۚ فَإِن كَانَ الَّذِي عَلَيْهِ الْحَقُّ سَفِيهًا أَوْ ضَعِيفًا أَوْ لَا يَسْتَطِيعُ أَن يُمِلَّ هُوَ فَلْيُمْلِلْ وَلِيُّهُ بِالْعَدْلِ ۚ وَاسْتَشْهِدُوا شَهِيدَيْنِ مِن رِّجَالِكُمْ ۖ فَإِن لَّمْ يَكُونَا رَجُلَيْنِ فَرَجُلٌ وَامْرَأَتَانِ مِمَّن تَرْضَوْنَ مِنَ الشُّهَدَاءِ أَن تَضِلَّ إِحْدَاهُمَا فَتُذَكِّرَ إِحْدَاهُمَا الْأُخْرَىٰ ۚ وَلَا يَأْبَ الشُّهَدَاءُ إِذَا مَا دُعُوا ۚ وَلَا تَسْأَمُوا أَن تَكْتُبُوهُ صَغِيرًا أَوْ كَبِيرًا إِلَىٰ أَجَلِهِ ۚ ذَٰلِكُمْ أَقْسَطُ عِندَ اللَّهِ وَأَقْوَمُ لِلشَّهَادَةِ وَأَدْنَىٰ أَلَّا تَرْتَابُوا ۚ إِلَّا أَن تَكُونَ تِجَارَةً حَاضِرَةً تُدِيرُونَهَا بَيْنَكُمْ فَلَيْسَ عَلَيْكُمْ جُنَاحٌ أَلَّا تَكْتُبُوهَا ۗ وَأَشْهِدُوا إِذَا تَبَايَعْتُمْ ۚ وَلَا يُضَارَّ كَاتِبٌ وَلَا شَهِيدٌ ۚ وَإِن تَفْعَلُوا فَإِنَّهُ فُسُوقٌ بِكُمْ ۗ وَاتَّقُوا اللَّهَ ۖ وَيُعَلِّمُكُمُ اللَّهُ ۗ وَاللَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ", explication: "Ô croyants ! Quand vous contractez une dette à terme fixe, écrivez-la. Qu'un scribe l'écrive avec justice entre vous. Qu'aucun scribe ne refuse d'écrire. Que celui qui doit la dette dicte et craigne Allah son Seigneur. Si c'est un incapable, un faible, ou qu'il ne sait pas dicter, que son tuteur dicte équitablement. Appelez deux témoins parmi vos hommes ; sinon un homme et deux femmes. Les témoins ne doivent pas refuser quand on les convoque." },
  { id: 283, arabic: "وَإِن كُنتُمْ عَلَىٰ سَفَرٍ وَلَمْ تَجِدُوا كَاتِبًا فَرِهَانٌ مَّقْبُوضَةٌ ۖ فَإِنْ أَمِنَ بَعْضُكُم بَعْضًا فَلْيُؤَدِّ الَّذِي اؤْتُمِنَ أَمَانَتَهُ وَلْيَتَّقِ اللَّهَ رَبَّهُ ۗ وَلَا تَكْتُمُوا الشَّهَادَةَ ۚ وَمَن يَكْتُمْهَا فَإِنَّهُ آثِمٌ قَلْبُهُ ۗ وَاللَّهُ بِمَا تَعْمَلُونَ عَلِيمٌ", explication: "Si vous êtes en voyage et ne trouvez pas de scribe, qu'il y ait un gage en mains. Si vous vous faites confiance l'un l'autre, que celui en qui on a confiance rende son dépôt et craigne Allah. Ne cachez pas le témoignage." },
  { id: 284, arabic: "لِّلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ وَإِن تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللَّهُ ۖ فَيَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَن يَشَاءُ ۗ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ", explication: "À Allah appartient tout ce qui est dans les cieux et sur la terre. Que vous montriez ce qui est en vous ou que vous le cachiez, Allah vous en demandera compte. Il pardonne à qui Il veut et châtie qui Il veut. Allah est Puissant sur toute chose." },
  { id: 285, arabic: "آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ", explication: "Le Messager croit en ce qui a été révélé à lui par son Seigneur, ainsi que les croyants. Tous croient en Allah, en Ses anges, en Ses livres et en Ses messagers. Nous ne faisons pas de distinction entre Ses messagers. Ils disent : nous entendons et nous obéissons. Seigneur, Ton pardon ! Et c'est vers Toi que sera le retour." },
  { id: 286, arabic: "لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ", explication: "Allah n'impose à aucune âme que ce qu'elle peut supporter. Elle a ce qu'elle a acquis et supporte ce qu'elle s'est acquise. Seigneur, ne nous punis pas si nous oublions ou nous trompons. Seigneur, ne nous charge pas d'un fardeau comme Tu as chargé ceux d'avant nous. Seigneur, ne nous impose pas ce qui dépasse notre force. Pardonne-nous, absous-nous et fais-nous miséricorde. Tu es notre Protecteur, accorde-nous la victoire sur les gens qui ont mécru." }
];
